import React, { useState, useEffect, useRef } from 'react';
import { UserProfile, HealthRecord, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, ChatMessage } from './types';
import { STORAGE_KEY, ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';
const PREMIUM_VPA = "9787551548@okbizaxis";
const MONTHLY_PRICE = 99;

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [searchId, setSearchId] = useState('');
  const [searchResults, setSearchResults] = useState<HealthRecord | null>(null);
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Payment States
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentStep, setPaymentStep] = useState<'summary' | 'verifying' | 'success'>('summary');

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setIsLoading(false);
      }
    };
    bootstrap();
  }, []);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId,
      isPremium: false
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    try {
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Failed to save to database.");
    } finally {
      setIsLoading(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsLoading(true);
    const inputId = (loginId || '').trim().toUpperCase();
    try {
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Health ID not found. Please double-check or register.");
      }
    } catch (err) {
      setAuthError("Database error occurred while logging in.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickUnlock = async (id: string) => {
    setLoginId(id);
    setIsLoading(true);
    try {
      const found = await dbService.getRecord(id);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, id);
        setIsAuth(true);
      } else {
        setAuthError("Previous Health ID session expired.");
      }
    } catch (err) {
      setAuthError("Error during quick login.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const initiatePaymentVerification = async () => {
    setPaymentStep('verifying');
    setTimeout(async () => {
      if (!currentUser) return;
      const expiry = new Date();
      expiry.setMonth(expiry.getMonth() + 1);
      const updatedUser = {
        ...currentUser,
        profile: { ...currentUser.profile, isPremium: true, subscriptionExpiry: expiry.toISOString() }
      };
      try {
        await dbService.saveRecord(updatedUser);
        setCurrentUser(updatedUser);
        setPaymentStep('success');
      } catch (err) {
        alert("Verification failed.");
        setPaymentStep('summary');
      }
    }, 2500);
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setShowAddModal(null);
    } catch (err) {
      alert("Error saving record.");
    }
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      alert("Error removing record.");
    }
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const getSeverityColor = (sev: string) => {
    switch (sev?.toLowerCase()) {
      case 'severe': case 'high': return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'moderate': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'mild': case 'low': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Initializing Secure Vault Protocols...</p>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="max-w-5xl w-full grid grid-cols-1 lg:grid-cols-12 bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-100 min-h-[700px] relative z-10 animate-pop-in">
          <div className="lg:col-span-5 bg-indigo-950 p-12 text-white flex flex-col justify-between">
            <div className="relative z-10">
              <div className="flex items-center gap-3 mb-12">
                <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-indigo-950 text-2xl shadow-xl">{ICONS.LOCK}</div>
                <h1 className="text-2xl font-black uppercase tracking-widest italic">{APP_NAME}</h1>
              </div>
              <h2 className="text-4xl font-bold leading-tight mb-4">Your Health, <br/><span className="text-indigo-400 underline decoration-indigo-500/30">Privately</span> Secured.</h2>
              <p className="text-indigo-200/80 text-lg">Local-first encrypted vault with clinical AI insights.</p>
            </div>
          </div>
          <div className="lg:col-span-7 p-12 flex flex-col justify-center bg-slate-50/50">
             {showRegSuccess ? (
                <div className="max-w-md mx-auto w-full text-center">
                  <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-3xl flex items-center justify-center text-3xl mx-auto mb-6"><i className="fas fa-check"></i></div>
                  <h3 className="text-2xl font-bold mb-4">Registration Successful!</h3>
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 mb-8">
                    <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">Your Unique Health ID</p>
                    <p className="text-2xl font-mono font-bold text-indigo-600">{showRegSuccess}</p>
                  </div>
                  <button onClick={completeRegistration} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl shadow-lg">Login to Vault</button>
                </div>
             ) : (
                <div className="max-w-md mx-auto w-full">
                  <div className="bg-slate-200/50 p-1 rounded-2xl flex mb-10">
                    <button onClick={() => setAuthMode('login')} className={`flex-1 py-3 text-xs font-bold rounded-xl transition-all ${authMode === 'login' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500'}`}>Login</button>
                    <button onClick={() => setAuthMode('register')} className={`flex-1 py-3 text-xs font-bold rounded-xl transition-all ${authMode === 'register' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500'}`}>Register</button>
                  </div>
                  {authError && <div className="mb-4 p-4 bg-rose-50 text-rose-600 rounded-2xl text-xs font-bold">{authError}</div>}
                  {authMode === 'login' ? (
                    <form onSubmit={handleLogin} className="space-y-6">
                      <input value={loginId} onChange={(e) => setLoginId(e.target.value)} className="w-full px-6 py-5 rounded-2xl bg-white border border-slate-200 text-xl font-mono uppercase focus:ring-4 focus:ring-indigo-500/10 outline-none" placeholder="HID-XXXX-XXXX" />
                      {lastHid && <button type="button" onClick={() => handleQuickUnlock(lastHid)} className="w-full p-4 bg-indigo-50 text-indigo-600 rounded-2xl text-xs font-bold">Quick Login: {lastHid}</button>}
                      <button type="submit" className="w-full bg-slate-900 text-white font-bold py-5 rounded-2xl text-lg">Enter Vault</button>
                    </form>
                  ) : (
                    <form onSubmit={handleRegister} className="space-y-4 max-h-[450px] overflow-y-auto pr-2 custom-scrollbar">
                      <input required name="name" className="w-full px-4 py-4 rounded-xl border border-slate-200 text-sm" placeholder="Full Name" />
                      <div className="grid grid-cols-2 gap-4">
                        <input required name="age" type="number" className="w-full px-4 py-4 rounded-xl border border-slate-200 text-sm" placeholder="Age" />
                        <select name="bloodGroup" className="w-full px-4 py-4 rounded-xl border border-slate-200 text-sm">
                          {['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                        </select>
                      </div>
                      <input required name="aadhaar" pattern="\d{12}" className="w-full px-4 py-4 rounded-xl border border-slate-200 text-sm" placeholder="Aadhaar Number" />
                      <input required name="dob" type="date" className="w-full px-4 py-4 rounded-xl border border-slate-200 text-sm" />
                      <div className="p-4 bg-indigo-50 rounded-2xl space-y-3">
                        <p className="text-[10px] font-bold text-indigo-600 uppercase">Emergency Contact</p>
                        <input required name="eName" className="w-full px-4 py-3 rounded-xl border border-slate-200 text-xs" placeholder="Contact Name" />
                        <input required name="ePhone" className="w-full px-4 py-3 rounded-xl border border-slate-200 text-xs" placeholder="Phone" />
                      </div>
                      <button type="submit" className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl">Register Identity</button>
                    </form>
                  )}
                </div>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout} isPremium={currentUser?.profile?.isPremium}>
      {activeTab === 'dashboard' ? (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className={`lg:col-span-2 rounded-[2rem] p-8 text-white shadow-2xl relative overflow-hidden ${currentUser?.profile?.isPremium ? 'bg-slate-900' : 'bg-indigo-600'}`}>
              <div className="relative z-10">
                <p className="text-[10px] font-bold uppercase tracking-widest opacity-60 mb-8">Digital Health Passport</p>
                <h1 className="text-4xl font-mono font-bold mb-8">{currentUser?.profile?.healthId}</h1>
                <div className="grid grid-cols-3 gap-4 pt-8 border-t border-white/10">
                  <div><p className="text-[8px] uppercase opacity-60">Blood Group</p><p className="font-bold text-lg">{currentUser?.profile?.bloodGroup}</p></div>
                  <div><p className="text-[8px] uppercase opacity-60">Age</p><p className="font-bold text-lg">{currentUser?.profile?.age}</p></div>
                  <div><p className="text-[8px] uppercase opacity-60">Gender</p><p className="font-bold text-lg">{currentUser?.profile?.gender}</p></div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-[2rem] p-8 shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-3xl mb-4 animate-pulse">
                <i className="fas fa-shield-alt"></i>
              </div>
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Vault Security</p>
              <p className="font-bold text-emerald-600">Active Encryption</p>
            </div>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {[
              { label: 'Conditions', val: (currentUser?.problems || []).length, icon: ICONS.MEDICAL },
              { label: 'Meds', val: (currentUser?.medications || []).length, icon: ICONS.MEDS },
              { label: 'Notes', val: (currentUser?.notes || []).length, icon: ICONS.NOTE },
              { label: 'Allergies', val: (currentUser?.allergies || []).length, icon: ICONS.ALLERGY },
            ].map((s, i) => (
              <div key={i} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center gap-4">
                <div className="text-indigo-600 text-xl">{s.icon}</div>
                <div><p className="text-[9px] font-bold text-slate-400 uppercase">{s.label}</p><p className="text-xl font-bold">{s.val}</p></div>
              </div>
            ))}
          </div>
        </div>
      ) : activeTab === 'records' ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 pb-24">
          <RecordCard title="Medical Problems" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
            <div className="space-y-3">
              {(currentUser?.problems || []).length === 0 && <p className="text-slate-400 text-xs text-center py-4 italic">No problems recorded</p>}
              {(currentUser?.problems || []).map(p => (
                <div key={p.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 transition-all hover:bg-white hover:shadow-md">
                  <div className="flex justify-between items-start mb-2">
                    <div>
                      <h4 className="font-bold text-slate-800">{p.condition}</h4>
                      <p className="text-[10px] text-slate-500"><i className="far fa-calendar-alt mr-1"></i> Since {p.onsetDate}</p>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className={`text-[9px] px-2 py-1 rounded-full border font-bold uppercase ${getSeverityColor(p.severity)}`}>
                        {p.severity}
                      </span>
                      <button onClick={() => removeMedicalItem('problems', p.id)} className="text-slate-300 hover:text-rose-500 transition-colors"><i className="fas fa-trash-alt"></i></button>
                    </div>
                  </div>
                  {p.notes && <p className="text-xs text-slate-600 mt-2 bg-white/50 p-2 rounded-lg border border-slate-100">{p.notes}</p>}
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Active Medications" icon={ICONS.MEDS} onAdd={() => setShowAddModal('medication')}>
             <div className="space-y-3">
              {(currentUser?.medications || []).length === 0 && <p className="text-slate-400 text-xs text-center py-4 italic">No active medications</p>}
              {(currentUser?.medications || []).map(m => (
                <div key={m.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 transition-all hover:bg-white hover:shadow-md">
                   <div className="flex justify-between items-start">
                    <div>
                      <h4 className="font-bold text-indigo-700">{m.name}</h4>
                      <div className="flex gap-3 mt-1 text-[10px] text-slate-500 font-medium">
                        <span><i className="fas fa-prescription mr-1"></i> {m.dosage}</span>
                        <span><i className="fas fa-clock mr-1"></i> {m.frequency}</span>
                      </div>
                    </div>
                    <button onClick={() => removeMedicalItem('medications', m.id)} className="text-slate-300 hover:text-rose-500"><i className="fas fa-trash-alt"></i></button>
                  </div>
                  <div className="mt-3 flex gap-2">
                     <span className="text-[8px] bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded uppercase font-bold">Duration: {m.duration}</span>
                  </div>
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Known Allergies" icon={ICONS.ALLERGY} onAdd={() => setShowAddModal('allergy')}>
             <div className="space-y-3">
              {(currentUser?.allergies || []).length === 0 && <p className="text-slate-400 text-xs text-center py-4 italic">No allergies recorded</p>}
              {(currentUser?.allergies || []).map(a => (
                <div key={a.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center group">
                  <div className="flex items-center gap-4">
                    <div className={`w-2 h-2 rounded-full ${a.severity === 'high' ? 'bg-rose-500 animate-pulse' : a.severity === 'moderate' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                    <div>
                      <h4 className="font-bold text-slate-800">{a.substance}</h4>
                      {a.reaction && <p className="text-[10px] text-slate-500 italic">Reaction: {a.reaction}</p>}
                    </div>
                  </div>
                  <button onClick={() => removeMedicalItem('allergies', a.id)} className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-rose-500 transition-all"><i className="fas fa-trash-alt"></i></button>
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Surgical History" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
             <div className="space-y-3">
              {(currentUser?.surgeries || []).length === 0 && <p className="text-slate-400 text-xs text-center py-4 italic">No surgical history</p>}
              {(currentUser?.surgeries || []).map(s => (
                <div key={s.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 transition-all hover:bg-white hover:shadow-md">
                   <div className="flex justify-between mb-2">
                      <h4 className="font-bold text-slate-800">{s.type}</h4>
                      <button onClick={() => removeMedicalItem('surgeries', s.id)} className="text-slate-300 hover:text-rose-500"><i className="fas fa-trash-alt"></i></button>
                   </div>
                   <div className="grid grid-cols-2 gap-2 text-[10px] text-slate-500">
                      <span><i className="far fa-calendar mr-1"></i> {s.date}</span>
                      <span><i className="fas fa-hospital mr-1"></i> {s.hospital}</span>
                   </div>
                </div>
              ))}
            </div>
          </RecordCard>

          <RecordCard title="Clinical Notes" icon={ICONS.NOTE} onAdd={() => setShowAddModal('note')} className="lg:col-span-2">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(currentUser?.notes || []).length === 0 && <p className="text-slate-400 text-xs text-center py-4 italic col-span-2">No clinical notes recorded</p>}
              {(currentUser?.notes || []).map(n => (
                <div key={n.id} className="p-5 bg-white rounded-2xl border border-slate-100 shadow-sm relative group transition-all hover:shadow-lg">
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex items-center gap-2">
                      <div className="w-8 h-8 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center text-xs font-bold">DR</div>
                      <div>
                        <p className="font-bold text-slate-800">Dr. {n.doctorName}</p>
                        <p className="text-[10px] text-slate-400 font-medium">{n.clinicName || 'Clinical Consult'} • {n.date}</p>
                      </div>
                    </div>
                    <button onClick={() => removeMedicalItem('notes', n.id)} className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-rose-500 transition-all"><i className="fas fa-trash-alt"></i></button>
                  </div>
                  <div className={`text-xs text-slate-600 leading-relaxed ${expandedId === n.id ? '' : 'line-clamp-3'}`}>
                    {n.note}
                  </div>
                  <button 
                    onClick={() => setExpandedId(expandedId === n.id ? null : n.id)}
                    className="mt-3 text-[10px] font-bold text-indigo-600 hover:text-indigo-800 uppercase tracking-wider"
                  >
                    {expandedId === n.id ? 'Show Less' : 'View Full Details'}
                  </button>
                </div>
              ))}
            </div>
          </RecordCard>
        </div>
      ) : activeTab === 'august' ? (
        <div className="h-[calc(100vh-12rem)] flex flex-col bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
           <div className="flex-grow overflow-y-auto space-y-4 mb-4 pr-2 custom-scrollbar">
             {chatHistory.length === 0 && (
               <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-40">
                 <div className="text-5xl mb-4">{ICONS.AI}</div>
                 <p className="font-bold">August AI is ready to analyze your vault.</p>
                 <p className="text-xs">Ask about clinical trends or general health guidance.</p>
               </div>
             )}
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                 <div className={`max-w-[80%] p-4 rounded-2xl text-sm ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-800'}`}>
                   {m.content}
                 </div>
               </div>
             ))}
             {isAiLoading && <div className="text-[10px] font-bold text-indigo-400 animate-pulse"><i className="fas fa-circle-notch fa-spin mr-2"></i> Analyzing records...</div>}
           </div>
           <div className="flex gap-2 border-t pt-4">
             <input value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && askAugustAI()} placeholder="Ask August AI..." className="flex-grow p-4 bg-slate-100 rounded-xl outline-none" />
             <button onClick={askAugustAI} disabled={!userQuery.trim() || isAiLoading} className="px-6 bg-indigo-600 text-white font-bold rounded-xl disabled:opacity-50">Send</button>
           </div>
        </div>
      ) : activeTab === 'subscription' ? (
        <div className="max-w-xl mx-auto py-12">
           <div className="bg-indigo-950 text-white rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden">
             <div className="relative z-10">
               <div className="inline-block px-3 py-1 bg-amber-500/20 text-amber-400 rounded-full text-[10px] font-bold uppercase mb-4">Premium Vault</div>
               <h2 className="text-3xl font-bold mb-6">Upgrade Your Security</h2>
               <div className="text-5xl font-black mb-8">₹{MONTHLY_PRICE}<span className="text-sm font-normal opacity-60"> /month</span></div>
               <ul className="space-y-4 mb-10 text-sm">
                 <li className="flex gap-2"><i className="fas fa-check text-emerald-400"></i> Unlimited August AI Sessions</li>
                 <li className="flex gap-2"><i className="fas fa-check text-emerald-400"></i> Advanced Clinical History</li>
                 <li className="flex gap-2"><i className="fas fa-check text-emerald-400"></i> Local Data Backup Tools</li>
               </ul>
               <button onClick={() => {setShowPaymentModal(true); setPaymentStep('summary');}} className="w-full py-4 bg-white text-indigo-950 font-bold rounded-2xl shadow-xl hover:scale-[1.02] active:scale-95 transition-all">
                 {currentUser?.profile?.isPremium ? "Manage Subscription" : "Subscribe Now"}
               </button>
             </div>
           </div>
        </div>
      ) : null}

      {/* Payment Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[2rem] p-8 shadow-2xl animate-pop-in">
             {paymentStep === 'summary' ? (
               <>
                 <h3 className="text-xl font-bold mb-6">Subscription Summary</h3>
                 <div className="bg-slate-50 p-6 rounded-2xl mb-6">
                    <div className="flex justify-between mb-2"><span>Monthly Plan</span><span className="font-bold">₹{MONTHLY_PRICE}</span></div>
                    <div className="flex justify-between text-xs text-slate-400"><span>Service Fee</span><span className="font-bold">₹0</span></div>
                 </div>
                 <div className="space-y-3">
                   <button onClick={initiatePaymentVerification} className="w-full py-4 bg-slate-900 text-white font-bold rounded-xl">Pay Securely</button>
                   <button onClick={() => setShowPaymentModal(false)} className="w-full py-2 text-xs text-slate-400 font-bold">Cancel</button>
                 </div>
               </>
             ) : paymentStep === 'verifying' ? (
               <div className="py-12 text-center">
                 <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                 <p className="font-bold">Authenticating Gateway...</p>
               </div>
             ) : (
               <div className="py-8 text-center">
                 <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-6"><i className="fas fa-check"></i></div>
                 <h3 className="text-2xl font-bold mb-2">Premium Active!</h3>
                 <p className="text-slate-500 text-sm mb-8">Your clinical vault is now fully unlocked.</p>
                 <button onClick={() => setShowPaymentModal(false)} className="w-full py-4 bg-indigo-600 text-white font-bold rounded-xl">Awesome</button>
               </div>
             )}
          </div>
        </div>
      )}

      {/* Add Record Modals */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[2rem] p-8 shadow-2xl animate-pop-in max-h-[90vh] overflow-y-auto custom-scrollbar">
            <h3 className="text-xl font-bold mb-6 capitalize">Add New {showAddModal}</h3>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), severity: f.get('severity'), onsetDate: f.get('date'), status: 'present', notes: f.get('notes') });
              if (showAddModal === 'medication') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), frequency: f.get('freq'), duration: f.get('duration') });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity'), reaction: f.get('reaction') });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-4">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition Name (e.g. Hypertension)" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  <div className="grid grid-cols-2 gap-2">
                    <select name="severity" className="w-full p-4 bg-slate-50 rounded-xl outline-none">
                      <option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option>
                    </select>
                    <input required type="date" name="date" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  </div>
                  <textarea name="notes" placeholder="Notes (Optional)" className="w-full p-4 bg-slate-50 rounded-xl h-24 outline-none"></textarea>
                </>
              )}
              {showAddModal === 'medication' && (
                <>
                  <input required name="name" placeholder="Medication Name" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  <div className="grid grid-cols-2 gap-2">
                    <input required name="dosage" placeholder="Dosage (e.g. 500mg)" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                    <input required name="freq" placeholder="Frequency (e.g. 2x Daily)" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  </div>
                  <input required name="duration" placeholder="Duration (e.g. 5 Days)" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                </>
              )}
              {showAddModal === 'allergy' && (
                <>
                  <input required name="substance" placeholder="Allergen (e.g. Peanuts, Penicillin)" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  <select name="severity" className="w-full p-4 bg-slate-50 rounded-xl outline-none">
                    <option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option>
                  </select>
                  <input name="reaction" placeholder="Reaction (e.g. Rashes, Anaphylaxis)" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                </>
              )}
              {showAddModal === 'surgery' && (
                <>
                  <input required name="type" placeholder="Procedure Name" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  <input required type="date" name="date" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  <input required name="hospital" placeholder="Hospital/Clinic" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                </>
              )}
              {showAddModal === 'note' && (
                <>
                  <div className="grid grid-cols-2 gap-2">
                    <input required name="doc" placeholder="Doctor Name" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                    <input required type="date" name="date" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  </div>
                  <input name="clinic" placeholder="Clinic/Hospital Name" className="w-full p-4 bg-slate-50 rounded-xl outline-none" />
                  <textarea required name="note" placeholder="Consultation details, observations, and recommendations..." className="w-full p-4 bg-slate-50 rounded-xl h-40 outline-none"></textarea>
                </>
              )}
              <div className="flex gap-2 pt-4">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-4 bg-slate-100 rounded-xl font-bold">Cancel</button>
                <button type="submit" className="flex-1 py-4 bg-indigo-600 text-white font-bold rounded-xl shadow-lg">Save to Vault</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthRecord, ChatMessage } from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';
const MONTHLY_PRICE = 99;

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentStep, setPaymentStep] = useState<'summary' | 'verifying' | 'success'>('summary');

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    bootstrap();
  }, []);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId,
      isPremium: false
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    try {
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Failed to save to database.");
    } finally {
      setIsLoading(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsLoading(true);
    const inputId = (loginId || '').trim().toUpperCase();
    try {
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Health ID not found. Check your ID or Register.");
      }
    } catch (err) {
      setAuthError("Database error occurred while logging in.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickUnlock = async (id: string) => {
    setLoginId(id);
    setIsLoading(true);
    try {
      const found = await dbService.getRecord(id);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, id);
        setIsAuth(true);
      } else {
        setAuthError("Previous Health ID session expired.");
      }
    } catch (err) {
      setAuthError("Error during quick login.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const initiatePaymentVerification = async () => {
    setPaymentStep('verifying');
    setTimeout(async () => {
      if (!currentUser) return;
      const expiry = new Date();
      expiry.setMonth(expiry.getMonth() + 1);
      const updatedUser = {
        ...currentUser,
        profile: { ...currentUser.profile, isPremium: true, subscriptionExpiry: expiry.toISOString() }
      };
      try {
        await dbService.saveRecord(updatedUser);
        setCurrentUser(updatedUser);
        setPaymentStep('success');
      } catch (err) {
        alert("Verification failed.");
        setPaymentStep('summary');
      }
    }, 2500);
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setShowAddModal(null);
    } catch (err) {
      alert("Error saving record.");
    }
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      alert("Error removing record.");
    }
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const getSeverityColor = (sev: string) => {
    switch (sev?.toLowerCase()) {
      case 'severe': case 'high': return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'moderate': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'mild': case 'low': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center relative overflow-hidden">
        <div className="absolute inset-0 opacity-20">
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500 rounded-full blur-[120px]"></div>
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-500 rounded-full blur-[120px]"></div>
        </div>
        <div className="text-center relative z-10">
          <div className="w-20 h-20 bg-indigo-600/20 backdrop-blur-xl rounded-3xl flex items-center justify-center text-indigo-400 text-3xl mx-auto mb-6 border border-indigo-500/30 pulse-glow shadow-[0_0_50px_-10px_rgba(79,70,229,0.5)]">
            <i className="fas fa-shield-virus"></i>
          </div>
          <div className="space-y-2">
            <h1 className="text-white font-black tracking-tighter text-2xl uppercase italic">{APP_NAME}</h1>
            <p className="text-slate-500 font-bold uppercase tracking-[0.3em] text-[10px]">Secure Vault Initializing</p>
          </div>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 lg:p-8">
        <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-12 bg-white rounded-[3rem] auth-card overflow-hidden border border-slate-200/50 min-h-[750px] animate-pop-in">
          {/* Left Panel: Brand & Trust */}
          <div className="lg:col-span-5 bg-indigo-950 p-12 text-white flex flex-col justify-between relative overflow-hidden">
            {/* Background Decorations */}
            <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
                <div className="absolute top-[-20%] left-[-20%] w-full h-full bg-gradient-to-br from-indigo-400 to-transparent rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 right-0 p-8">
                    <i className="fas fa-dna text-[120px] rotate-12"></i>
                </div>
            </div>

            <div className="relative z-10">
              <div className="flex items-center gap-4 mb-16">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-indigo-950 text-2xl shadow-xl transform hover:rotate-6 transition-transform">
                    {ICONS.LOCK}
                </div>
                <div>
                    <h1 className="text-2xl font-black uppercase tracking-widest italic leading-none">{APP_NAME}</h1>
                    <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-wider mt-1">Health Records, Redefined.</p>
                </div>
              </div>

              <div className="space-y-6">
                <h2 className="text-5xl font-extrabold leading-[1.1] tracking-tight">
                  Your <span className="text-indigo-400">Clinical History</span>, <br/>
                  Locally Vaulted.
                </h2>
                <p className="text-indigo-200/70 text-lg font-medium leading-relaxed max-w-sm">
                  We don't store your data on servers. Everything stays encrypted on your device.
                </p>
              </div>
            </div>

            <div className="relative z-10 grid grid-cols-1 gap-4 mt-12">
                {[
                    { label: 'E2E Encryption', icon: 'fa-lock' },
                    { label: 'Local-First Privacy', icon: 'fa-microchip' },
                    { label: 'AI Driven Insights', icon: 'fa-brain' }
                ].map((badge, idx) => (
                    <div key={idx} className="flex items-center gap-3 bg-white/5 border border-white/10 rounded-2xl p-4 backdrop-blur-md">
                        <div className="w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center text-indigo-400 text-sm">
                            <i className={`fas ${badge.icon}`}></i>
                        </div>
                        <span className="text-xs font-bold uppercase tracking-wide opacity-80">{badge.label}</span>
                    </div>
                ))}
            </div>
          </div>

          {/* Right Panel: Form */}
          <div className="lg:col-span-7 p-8 lg:p-16 flex flex-col justify-center bg-slate-50/30">
             {showRegSuccess ? (
                <div className="max-w-md mx-auto w-full text-center animate-slide-in">
                  <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2rem] flex items-center justify-center text-4xl mx-auto mb-8 shadow-xl border border-emerald-100">
                    <i className="fas fa-id-badge"></i>
                  </div>
                  <h3 className="text-3xl font-black mb-4 text-slate-800 tracking-tight">Vault Created!</h3>
                  <p className="text-slate-500 font-medium mb-8">This is your unique Identity key. Keep it safe – it cannot be recovered if lost.</p>

                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 mb-10 shadow-sm group hover:border-indigo-500 transition-colors">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Patient Health ID</p>
                    <p className="text-3xl font-mono font-black text-indigo-600 tracking-wider group-hover:scale-105 transition-transform">{showRegSuccess}</p>
                  </div>

                  <button onClick={completeRegistration} className="w-full bg-slate-900 text-white font-bold py-5 rounded-[2rem] shadow-xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3">
                    Open Your Vault <i className="fas fa-arrow-right"></i>
                  </button>
                </div>
             ) : (
                <div className="max-w-md mx-auto w-full">
                  <div className="relative bg-slate-200/50 p-1.5 rounded-[2rem] flex mb-12 border border-slate-300/30">
                    <div className={`absolute top-1.5 bottom-1.5 left-1.5 w-[calc(50%-6px)] bg-white rounded-[1.7rem] shadow-lg tab-slider ${authMode === 'register' ? 'translate-x-[calc(100%+6px)]' : 'translate-x-0'}`}></div>
                    <button onClick={() => setAuthMode('login')} className={`relative z-10 flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-colors ${authMode === 'login' ? 'text-indigo-600' : 'text-slate-500'}`}>Existing User</button>
                    <button onClick={() => setAuthMode('register')} className={`relative z-10 flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-colors ${authMode === 'register' ? 'text-indigo-600' : 'text-slate-500'}`}>New Patient</button>
                  </div>

                  {authError && (
                    <div className="mb-6 p-5 bg-rose-50 border border-rose-100 text-rose-600 rounded-3xl text-xs font-bold flex items-center gap-3 animate-slide-in">
                        <i className="fas fa-exclamation-circle text-lg"></i>
                        {authError}
                    </div>
                  )}

                  {authMode === 'login' ? (
                    <form onSubmit={handleLogin} className="space-y-6 animate-slide-in">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Identity Key</label>
                        <div className="relative group">
                            <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-slate-400 group-focus-within:text-indigo-600 transition-colors">
                                <i className="fas fa-key"></i>
                            </div>
                            <input 
                                value={loginId} 
                                onChange={(e) => setLoginId(e.target.value.toUpperCase())} 
                                className="w-full pl-14 pr-6 py-6 rounded-3xl bg-white border border-slate-200 text-xl font-mono uppercase focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all shadow-sm" 
                                placeholder="HID-XXXX-XXXX" 
                            />
                        </div>
                      </div>

                      {lastHid && (
                        <button type="button" onClick={() => handleQuickUnlock(lastHid)} className="w-full p-5 bg-indigo-50/50 border border-indigo-100 hover:bg-indigo-50 text-indigo-600 rounded-3xl text-xs font-bold flex items-center justify-between group transition-all">
                            <div className="flex items-center gap-3">
                                <i className="fas fa-fingerprint text-lg"></i>
