import React, { useState, useEffect } from 'react';
import { UserProfile, HealthRecord, ChatMessage } from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';
const MONTHLY_PRICE = 99;

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentStep, setPaymentStep] = useState<'summary' | 'verifying' | 'success'>('summary');

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    bootstrap();
  }, []);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    const healthId = `HID-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId,
      isPremium: false
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: []
    };

    try {
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Failed to save to database.");
    } finally {
      setIsLoading(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsLoading(true);
    const inputId = (loginId || '').trim().toUpperCase();
    try {
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Health ID not found. Check your ID or Register.");
      }
    } catch (err) {
      setAuthError("Database error occurred while logging in.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickUnlock = async (id: string) => {
    setLoginId(id);
    setIsLoading(true);
    try {
      const found = await dbService.getRecord(id);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, id);
        setIsAuth(true);
      } else {
        setAuthError("Previous Health ID session expired.");
      }
    } catch (err) {
      setAuthError("Error during quick login.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const initiatePaymentVerification = async () => {
    setPaymentStep('verifying');
    setTimeout(async () => {
      if (!currentUser) return;
      const expiry = new Date();
      expiry.setMonth(expiry.getMonth() + 1);
      const updatedUser = {
        ...currentUser,
        profile: { ...currentUser.profile, isPremium: true, subscriptionExpiry: expiry.toISOString() }
      };
      try {
        await dbService.saveRecord(updatedUser);
        setCurrentUser(updatedUser);
        setPaymentStep('success');
      } catch (err) {
        alert("Verification failed.");
        setPaymentStep('summary');
      }
    }, 2500);
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setShowAddModal(null);
    } catch (err) {
      alert("Error saving record.");
    }
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      alert("Error removing record.");
    }
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    setUserQuery('');
    setIsAiLoading(true);
    const response = await analyzeHealthRecord(currentUser, userQuery);
    setChatHistory(prev => [...prev, { role: 'assistant', content: response, timestamp: Date.now() }]);
    setIsAiLoading(false);
  };

  const getSeverityColor = (sev: string) => {
    switch (sev?.toLowerCase()) {
      case 'severe': case 'high': return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'moderate': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'mild': case 'low': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getSeverityAccent = (sev: string) => {
    switch (sev?.toLowerCase()) {
      case 'severe': case 'high': return 'border-l-rose-500';
      case 'moderate': return 'border-l-amber-500';
      case 'mild': case 'low': return 'border-l-emerald-500';
      default: return 'border-l-slate-300';
    }
  };

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center relative overflow-hidden">
        <div className="absolute inset-0 opacity-20">
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500 rounded-full blur-[120px]"></div>
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-500 rounded-full blur-[120px]"></div>
        </div>
        <div className="text-center relative z-10">
          <div className="w-20 h-20 bg-indigo-600/20 backdrop-blur-xl rounded-3xl flex items-center justify-center text-indigo-400 text-3xl mx-auto mb-6 border border-indigo-500/30 pulse-glow shadow-[0_0_50px_-10px_rgba(79,70,229,0.5)]">
            <i className="fas fa-shield-virus"></i>
          </div>
          <div className="space-y-2">
            <h1 className="text-white font-black tracking-tighter text-2xl uppercase italic">{APP_NAME}</h1>
            <p className="text-slate-500 font-bold uppercase tracking-[0.3em] text-[10px]">Secure Vault Initializing</p>
          </div>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 lg:p-8">
        <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-12 bg-white rounded-[3rem] auth-card overflow-hidden border border-slate-200/50 min-h-[750px] animate-pop-in">
          {/* Left Panel: Brand & Trust */}
          <div className="lg:col-span-5 bg-indigo-950 p-12 text-white flex flex-col justify-between relative overflow-hidden">
            {/* Background Decorations */}
            <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
                <div className="absolute top-[-20%] left-[-20%] w-full h-full bg-gradient-to-br from-indigo-400 to-transparent rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 right-0 p-8">
                    <i className="fas fa-dna text-[120px] rotate-12"></i>
                </div>
            </div>

            <div className="relative z-10">
              <div className="flex items-center gap-4 mb-16">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-indigo-950 text-2xl shadow-xl transform hover:rotate-6 transition-transform">
                    {ICONS.LOCK}
                </div>
                <div>
                    <h1 className="text-2xl font-black uppercase tracking-widest italic leading-none">{APP_NAME}</h1>
                    <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-wider mt-1">Health Records, Redefined.</p>
                </div>
              </div>

              <div className="space-y-6">
                <h2 className="text-5xl font-extrabold leading-[1.1] tracking-tight">
                  Your <span className="text-indigo-400">Clinical History</span>, <br/>
                  Locally Vaulted.
                </h2>
                <p className="text-indigo-200/70 text-lg font-medium leading-relaxed max-w-sm">
                  We don't store your data on servers. Everything stays encrypted on your device.
                </p>
              </div>
            </div>

            <div className="relative z-10 grid grid-cols-1 gap-4 mt-12">
                {[
                    { label: 'E2E Encryption', icon: 'fa-lock' },
                    { label: 'Local-First Privacy', icon: 'fa-microchip' },
                    { label: 'AI Driven Insights', icon: 'fa-brain' }
                ].map((badge, idx) => (
                    <div key={idx} className="flex items-center gap-3 bg-white/5 border border-white/10 rounded-2xl p-4 backdrop-blur-md">
                        <div className="w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center text-indigo-400 text-sm">
                            <i className={`fas ${badge.icon}`}></i>
                        </div>
                        <span className="text-xs font-bold uppercase tracking-wide opacity-80">{badge.label}</span>
                    </div>
                ))}
            </div>
          </div>

          {/* Right Panel: Form */}
          <div className="lg:col-span-7 p-8 lg:p-16 flex flex-col justify-center bg-slate-50/30">
             {showRegSuccess ? (
                <div className="max-w-md mx-auto w-full text-center animate-slide-in">
                  <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2rem] flex items-center justify-center text-4xl mx-auto mb-8 shadow-xl border border-emerald-100">
                    <i className="fas fa-id-badge"></i>
                  </div>
                  <h3 className="text-3xl font-black mb-4 text-slate-800 tracking-tight">Vault Created!</h3>
                  <p className="text-slate-500 font-medium mb-8">This is your unique Identity key. Keep it safe – it cannot be recovered if lost.</p>

                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 mb-10 shadow-sm group hover:border-indigo-500 transition-colors">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Patient Health ID</p>
                    <p className="text-3xl font-mono font-black text-indigo-600 tracking-wider group-hover:scale-105 transition-transform">{showRegSuccess}</p>
                  </div>

                  <button onClick={completeRegistration} className="w-full bg-slate-900 text-white font-bold py-5 rounded-[2rem] shadow-xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3">
                    Open Your Vault <i className="fas fa-arrow-right"></i>
                  </button>
                </div>
             ) : (
                <div className="max-w-md mx-auto w-full">
                  <div className="relative bg-slate-200/50 p-1.5 rounded-[2rem] flex mb-12 border border-slate-300/30">
                    <div className={`absolute top-1.5 bottom-1.5 left-1.5 w-[calc(50%-6px)] bg-white rounded-[1.7rem] shadow-lg tab-slider ${authMode === 'register' ? 'translate-x-[calc(100%+6px)]' : 'translate-x-0'}`}></div>
                    <button onClick={() => setAuthMode('login')} className={`relative z-10 flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-colors ${authMode === 'login' ? 'text-indigo-600' : 'text-slate-500'}`}>Existing User</button>
                    <button onClick={() => setAuthMode('register')} className={`relative z-10 flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-colors ${authMode === 'register' ? 'text-indigo-600' : 'text-slate-500'}`}>New Patient</button>
                  </div>

                  {authError && (
                    <div className="mb-6 p-5 bg-rose-50 border border-rose-100 text-rose-600 rounded-3xl text-xs font-bold flex items-center gap-3 animate-slide-in">
                        <i className="fas fa-exclamation-circle text-lg"></i>
                        {authError}
                    </div>
                  )}

                  {authMode === 'login' ? (
                    <form onSubmit={handleLogin} className="space-y-6 animate-slide-in">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Identity Key</label>
                        <div className="relative group">
                            <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-slate-400 group-focus-within:text-indigo-600 transition-colors">
                                <i className="fas fa-key"></i>
                            </div>
                            <input 
                                value={loginId} 
                                onChange={(e) => setLoginId(e.target.value.toUpperCase())} 
                                className="w-full pl-14 pr-6 py-6 rounded-3xl bg-white border border-slate-200 text-xl font-mono uppercase focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all shadow-sm" 
                                placeholder="HID-XXXX-XXXX" 
                            />
                        </div>
                      </div>

                      {lastHid && (
                        <button type="button" onClick={() => handleQuickUnlock(lastHid)} className="w-full p-5 bg-indigo-50/50 border border-indigo-100 hover:bg-indigo-50 text-indigo-600 rounded-3xl text-xs font-bold flex items-center justify-between group transition-all">
                            <div className="flex items-center gap-3">
                                <i className="fas fa-fingerprint text-lg"></i>
                                <span>Unlock Previous Session</span>
                            </div>
                            <span className="font-mono text-[10px] opacity-60">{lastHid}</span>
                        </button>
                      )}

                      <button type="submit" className="w-full bg-slate-900 text-white font-black py-6 rounded-[2rem] text-lg hover:bg-indigo-600 hover:shadow-2xl hover:shadow-indigo-500/30 transition-all flex items-center justify-center gap-3 active:scale-[0.98]">
                        Unlock Vault <i className="fas fa-unlock"></i>
                      </button>
                    </form>
                  ) : (
                    <form onSubmit={handleRegister} className="space-y-6 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar animate-slide-in pb-4">
                      <div className="space-y-4">
                        <div className="bg-white p-6 rounded-3xl border border-slate-200/60 shadow-sm space-y-4">
                            <p className="text-[9px] font-black text-indigo-600 uppercase tracking-widest mb-2">1. Personal Profile</p>
                            <input required name="name" className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-200 text-sm focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all" placeholder="Full Name (Legal)" />
                            <div className="grid grid-cols-2 gap-4">
                                <input required name="age" type="number" className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-200 text-sm outline-none" placeholder="Age" />
