                 currentUser.interactions.map((interaction) => (
                   <div key={interaction.id} className="relative group">
                      <div className="absolute top-4 left-[-31px] w-4 h-4 rounded-full bg-white border-4 border-indigo-500 z-10 shadow-sm group-hover:scale-125 transition-transform"></div>
                      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 group-hover:shadow-xl group-hover:border-indigo-100 transition-all">
                         <div className="flex items-center justify-between mb-6">
                            <span className="text-[10px] bg-slate-100 text-slate-500 px-4 py-1.5 rounded-full font-black uppercase tracking-widest">
                               {new Date(interaction.timestamp).toLocaleString()}
                            </span>
                            <div className="flex gap-2">
                               <button className="text-slate-300 hover:text-indigo-600 transition-colors"><i className="fas fa-external-link-alt"></i></button>
                            </div>
                         </div>
                         <div className="space-y-6">
                            <div className="flex gap-4 items-start">
                               <div className="w-8 h-8 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center text-xs shrink-0"><i className="fas fa-user"></i></div>
                               <p className="text-slate-700 font-bold leading-relaxed">{interaction.query}</p>
                            </div>
                            <div className="flex gap-4 items-start bg-slate-50/50 p-6 rounded-3xl border border-slate-100">
                               <div className="w-8 h-8 rounded-full bg-slate-900 text-white flex items-center justify-center text-xs shrink-0"><i className="fas fa-robot"></i></div>
                               <div className="text-sm text-slate-600 leading-relaxed font-medium line-clamp-4 group-hover:line-clamp-none transition-all duration-500">
                                  {interaction.response}
                               </div>
                            </div>
                         </div>
                      </div>
                   </div>
                 ))
               )}
            </div>
          </div>
        </div>
      ) : activeTab === 'subscription' ? (
        <div className="max-w-2xl mx-auto py-12">
           <div className="bg-indigo-950 text-white rounded-[3rem] p-12 shadow-[0_40px_80px_-20px_rgba(15,23,42,0.3)] relative overflow-hidden group">
             <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none group-hover:scale-110 transition-transform">
                <i className="fas fa-crown text-[280px]"></i>
             </div>
             <div className="relative z-10">
               <div className="inline-block px-4 py-1.5 bg-amber-500/20 text-amber-400 rounded-full text-[10px] font-black uppercase tracking-[0.2em] mb-8 border border-amber-400/20">Clinical Premium</div>
               <h2 className="text-4xl lg:text-5xl font-black mb-8 leading-tight tracking-tight">Upgrade Your <br/><span className="text-indigo-400">Vault Security</span></h2>
               <div className="flex items-baseline gap-2 mb-12">
                    <span className="text-6xl font-black">₹{MONTHLY_PRICE}</span>
                    <span className="text-sm font-bold opacity-40 uppercase tracking-widest">/ Month</span>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-12">
                    {[
                        "Unlimited August AI Sessions",
                        "Advanced Interaction Alerts",
                        "Device-to-Device Sync",
                        "Encrypted Export Formats",
                        "Priority Medical Support",
                        "Biometric Unlock Support"
                    ].map((feature, i) => (
                        <div key={i} className="flex items-center gap-3 text-sm font-medium opacity-80">
                            <i className="fas fa-check-circle text-emerald-400 text-lg"></i>
                            {feature}
                        </div>
                    ))}
               </div>
               <button onClick={() => {setShowPaymentModal(true); setPaymentStep('summary');}} className="w-full py-6 bg-white text-indigo-950 font-black rounded-[2rem] shadow-2xl hover:bg-indigo-50 hover:scale-[1.02] active:scale-[0.98] transition-all uppercase tracking-widest text-lg">
                 {currentUser?.profile?.isPremium ? "Active Subscription" : "Unlock Full Vault"}
               </button>
             </div>
           </div>
        </div>
      ) : null}

      {/* Payment Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl">
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-pop-in border border-slate-200/50">
             {paymentStep === 'summary' ? (
               <>
                 <div className="flex items-center gap-4 mb-8">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-2xl shadow-inner"><i className="fas fa-receipt"></i></div>
                    <h3 className="text-2xl font-black tracking-tight">Checkout</h3>
                 </div>
                 <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 mb-10 shadow-inner">
                    <div className="flex justify-between mb-4"><span className="font-bold text-slate-500 uppercase text-[10px] tracking-widest">Plan Name</span><span className="font-black">Clinical Monthly</span></div>
                    <div className="flex justify-between mb-2"><span className="font-bold text-slate-500 uppercase text-[10px] tracking-widest">Total Price</span><span className="font-black text-2xl text-indigo-600">₹{MONTHLY_PRICE}</span></div>
                    <div className="pt-4 border-t border-slate-200 mt-4 text-[10px] text-slate-400 font-bold uppercase tracking-wide">Secure Transaction Encrypted via SSL</div>
                 </div>
                 <div className="space-y-4">
                   <button onClick={initiatePaymentVerification} className="w-full py-5 bg-slate-900 text-white font-black rounded-3xl shadow-xl hover:bg-indigo-600 transition-all uppercase tracking-widest flex items-center justify-center gap-3">
                        Pay Securely <i className="fas fa-lock text-sm"></i>
                   </button>
                   <button onClick={() => setShowPaymentModal(false)} className="w-full py-3 text-xs text-slate-400 font-black uppercase tracking-[0.2em] hover:text-slate-600 transition-colors">Abort Transaction</button>
                 </div>
               </>
             ) : paymentStep === 'verifying' ? (
               <div className="py-20 text-center">
                 <div className="w-20 h-20 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-10 shadow-[0_0_30px_-10px_rgba(79,70,229,0.5)]"></div>
                 <p className="font-black text-xl tracking-tight mb-2">Authenticating Signature...</p>
                 <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Do not refresh your secure vault</p>
               </div>
             ) : (
               <div className="py-12 text-center animate-pop-in">
                 <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2.5rem] flex items-center justify-center text-5xl mx-auto mb-10 shadow-xl border border-emerald-100">
                    <i className="fas fa-crown"></i>
                 </div>
                 <h3 className="text-3xl font-black mb-4 tracking-tight">Premium Active!</h3>
                 <p className="text-slate-500 font-medium mb-10 leading-relaxed">Your clinical vault is now fully unlocked. Enjoy unrestricted August AI sessions and biometric sync.</p>
                 <button onClick={() => setShowPaymentModal(false)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl hover:shadow-indigo-500/30 transition-all uppercase tracking-widest">Explore Premium Features</button>
               </div>
             )}
          </div>
        </div>
      )}

      {/* Add Record Modals */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xl">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl animate-pop-in max-h-[90vh] overflow-y-auto custom-scrollbar border border-slate-200">
            <div className="flex items-center gap-4 mb-10">
                <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">
                    {showAddModal === 'problem' ? ICONS.MEDICAL : 
                     showAddModal === 'medication' ? ICONS.MEDS :
                     showAddModal === 'allergy' ? ICONS.ALLERGY :
                     showAddModal === 'surgery' ? ICONS.SURGERY : ICONS.NOTE}
                </div>
                <h3 className="text-2xl font-black tracking-tight capitalize">New {showAddModal} Entry</h3>
            </div>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), severity: f.get('severity'), onsetDate: f.get('date'), status: 'present', notes: f.get('notes') });
              if (showAddModal === 'medication') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), frequency: f.get('freq'), duration: f.get('duration') });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity'), reaction: f.get('reaction') });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-5">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition Name (e.g. Type II Diabetes)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:border-indigo-500 transition-colors font-medium" />
                  <div className="grid grid-cols-2 gap-4">
                    <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px] tracking-widest">
                      <option value="mild">Mild Case</option><option value="moderate">Moderate Case</option><option value="severe">Severe Case</option>
                    </select>
                    <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  </div>
                  <textarea name="notes" placeholder="Detailed symptoms or diagnostic notes..." className="w-full p-6 bg-slate-50 border border-slate-200 rounded-3xl h-32 outline-none focus:border-indigo-500 transition-colors text-sm"></textarea>
                </>
              )}
              {showAddModal === 'medication' && (
                <>
                  <input required name="name" placeholder="Medication Brand/Generic Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  <div className="grid grid-cols-2 gap-4">
                    <input required name="dosage" placeholder="Dosage (e.g. 5mg)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                    <input required name="freq" placeholder="Freq (e.g. Post-Meal)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  </div>
                  <input required name="duration" placeholder="Expected Duration (e.g. 14 Days)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                </>
              )}
              {showAddModal === 'allergy' && (
                <>
                  <input required name="substance" placeholder="Allergen (e.g. Penicillin, Pollen)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px] tracking-widest">
                    <option value="low">Low Sensitivity</option><option value="moderate">Moderate Sensitivity</option><option value="high">High Sensitivity</option>
                  </select>
                  <input name="reaction" placeholder="Observed Reaction (e.g. Urticaria)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                </>
              )}
              {showAddModal === 'surgery' && (
                <>
                  <input required name="type" placeholder="Procedure Name (e.g. Appendectomy)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  <input required name="hospital" placeholder="Hospital/Medical Center" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                </>
              )}
              {showAddModal === 'note' && (
                <>
                  <div className="grid grid-cols-2 gap-4">
                    <input required name="doc" placeholder="Physician's Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                    <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  </div>
                  <input name="clinic" placeholder="Clinical Facility Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-medium" />
                  <textarea required name="note" placeholder="Clinical summary, prescriptions, and advice..." className="w-full p-6 bg-slate-50 border border-slate-200 rounded-3xl h-48 outline-none text-sm"></textarea>
                </>
              )}
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 bg-slate-100 rounded-3xl font-black uppercase tracking-widest text-[10px] text-slate-500 hover:bg-slate-200 transition-colors">Discard</button>
                <button type="submit" className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 transition-all uppercase tracking-widest text-[10px]">Commit to Vault</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, HealthRecord, ChatMessage, Interaction } from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';
const MONTHLY_PRICE = 99;

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allPatients, setAllPatients] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [globalSearchTerm, setGlobalSearchTerm] = useState('');
  const [patientLookupTerm, setPatientLookupTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentStep, setPaymentStep] = useState<'summary' | 'verifying' | 'success'>('summary');

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
        // Load all patients for lookup feature
        const records = await dbService.getAllRecords();
        setAllPatients(records);
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    bootstrap();
  }, [isAuth]);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    // Generate a 6-digit Health ID for better memorability as requested
    const randomCode = Math.random().toString(36).substring(2, 8).toUpperCase();
    const healthId = `HID-${randomCode}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      emergencyContact: {
        name: (formData.get('eName') as string) || '',
        phone: (formData.get('ePhone') as string) || ''
      },
      healthId,
      isPremium: false
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], interactions: []
    };

    try {
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Failed to save to database.");
    } finally {
      setIsLoading(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsLoading(true);
    const inputId = (loginId || '').trim().toUpperCase();
    try {
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Health ID not found. Check your ID or Register.");
      }
    } catch (err) {
      setAuthError("Database error occurred while logging in.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickUnlock = async (id: string) => {
    setLoginId(id);
    setIsLoading(true);
    try {
      const found = await dbService.getRecord(id);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, id);
        setIsAuth(true);
      } else {
        setAuthError("Previous Health ID session expired.");
      }
    } catch (err) {
      setAuthError("Error during quick login.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setLoginId('');
  };

  const initiatePaymentVerification = async () => {
    setPaymentStep('verifying');
    setTimeout(async () => {
      if (!currentUser) return;
      const expiry = new Date();
      expiry.setMonth(expiry.getMonth() + 1);
      const updatedUser = {
        ...currentUser,
        profile: { ...currentUser.profile, isPremium: true, subscriptionExpiry: expiry.toISOString() }
      };
      try {
        await dbService.saveRecord(updatedUser);
        setCurrentUser(updatedUser);
        setPaymentStep('success');
      } catch (err) {
        alert("Verification failed.");
        setPaymentStep('summary');
      }
    }, 2500);
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setShowAddModal(null);
    } catch (err) {
      alert("Error saving record.");
    }
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };
    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      alert("Error removing record.");
    }
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    const currentQ = userQuery;
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, currentQ);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);

      // Persist to history
      const newInteraction: Interaction = {
        id: Date.now().toString(),
        query: currentQ,
        response: response,
        timestamp: Date.now()
      };

      const updatedUser = {
        ...currentUser,
        interactions: [newInteraction, ...(currentUser.interactions || [])]
      };
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
  };

  const filteredSearchResults = useMemo(() => {
    if (!currentUser || !globalSearchTerm.trim()) return null;
    const term = globalSearchTerm.toLowerCase();
    return {
      problems: (currentUser.problems || []).filter(p => p.condition.toLowerCase().includes(term) || p.notes?.toLowerCase().includes(term)),
      medications: (currentUser.medications || []).filter(m => m.name.toLowerCase().includes(term) || m.prescribedBy?.toLowerCase().includes(term)),
      allergies: (currentUser.allergies || []).filter(a => a.substance.toLowerCase().includes(term) || a.reaction?.toLowerCase().includes(term)),
      surgeries: (currentUser.surgeries || []).filter(s => s.type.toLowerCase().includes(term) || s.hospital.toLowerCase().includes(term)),
      notes: (currentUser.notes || []).filter(n => n.doctorName.toLowerCase().includes(term) || n.note.toLowerCase().includes(term) || n.clinicName?.toLowerCase().includes(term))
    };
  }, [currentUser, globalSearchTerm]);

  const foundPatients = useMemo(() => {
    if (!patientLookupTerm.trim()) return [];
    const term = patientLookupTerm.toUpperCase();
    return allPatients.filter(p => p.profile.healthId.includes(term));
  }, [allPatients, patientLookupTerm]);

  const getSeverityColor = (sev: string) => {
    switch (sev?.toLowerCase()) {
      case 'severe': case 'high': return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'moderate': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'mild': case 'low': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getSeverityAccent = (sev: string) => {
    switch (sev?.toLowerCase()) {
      case 'severe': case 'high': return 'border-l-rose-500';
      case 'moderate': return 'border-l-amber-500';
      case 'mild': case 'low': return 'border-l-emerald-500';
      default: return 'border-l-slate-300';
    }
  };

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center relative overflow-hidden">
        <div className="absolute inset-0 opacity-20">
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500 rounded-full blur-[120px]"></div>
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-emerald-500 rounded-full blur-[120px]"></div>
        </div>
        <div className="text-center relative z-10">
          <div className="w-20 h-20 bg-indigo-600/20 backdrop-blur-xl rounded-3xl flex items-center justify-center text-indigo-400 text-3xl mx-auto mb-6 border border-indigo-500/30 pulse-glow shadow-[0_0_50px_-10px_rgba(79,70,229,0.5)]">
            <i className="fas fa-shield-virus"></i>
          </div>
          <div className="space-y-2">
            <h1 className="text-white font-black tracking-tighter text-2xl uppercase italic">{APP_NAME}</h1>
