              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-5">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  <div className="grid grid-cols-2 gap-4">
                    <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px] tracking-widest">
                      <option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option>
                    </select>
                    <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  </div>
                  <textarea name="notes" placeholder="Symptoms or diagnostic notes..." className="w-full p-6 bg-slate-50 border border-slate-200 rounded-3xl h-32 outline-none text-sm"></textarea>
                </>
              )}
              {showAddModal === 'medication' && (
                <>
                  <input required name="name" placeholder="Medication Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  <div className="grid grid-cols-2 gap-4">
                    <input required name="dosage" placeholder="Dosage" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                    <input required name="freq" placeholder="Frequency" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  </div>
                </>
              )}
              {showAddModal === 'allergy' && (
                <>
                  <input required name="substance" placeholder="Allergen" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px]">
                    <option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option>
                  </select>
                </>
              )}
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 bg-slate-100 rounded-3xl font-black uppercase tracking-widest text-[10px]">Discard</button>
                <button type="submit" className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl uppercase tracking-widest text-[10px]">Commit</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, HealthRecord, ChatMessage, Interaction } from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;
type PaymentStep = 'summary' | 'method' | 'verifying' | 'success';
type PlanType = 'pro' | 'family';

const PLANS = {
  pro: { name: 'Pro Vault', price: 99, features: ['Unlimited August AI', 'E2E Sync', 'Clinical Priority'] },
  family: { name: 'Family Shield', price: 299, features: ['Up to 4 Users', 'Biometric Lock', '24/7 Support'] }
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allPatients, setAllPatients] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [globalSearchTerm, setGlobalSearchTerm] = useState('');
  const [patientLookupTerm, setPatientLookupTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentStep, setPaymentStep] = useState<PaymentStep>('summary');
  const [selectedPlan, setSelectedPlan] = useState<PlanType>('pro');
  const [selectedMethod, setSelectedMethod] = useState<'card' | 'upi' | 'bank'>('upi');
  const [verificationSubStep, setVerificationSubStep] = useState('');

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
        const records = await dbService.getAllRecords();
        setAllPatients(records);
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setTimeout(() => setIsLoading(false), 800);
      }
    };
    bootstrap();
  }, [isAuth]);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsLoading(true);
    const formData = new FormData(e.currentTarget);
    const randomCode = Math.random().toString(36).substring(2, 8).toUpperCase();
    const healthId = `HID-${randomCode}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      healthId,
      isPremium: false,
      subscriptionPlan: 'standard'
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], interactions: []
    };

    try {
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Failed to save to database.");
    } finally {
      setIsLoading(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsLoading(true);
    const inputId = (loginId || '').trim().toUpperCase();
    try {
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Health ID not found.");
      }
    } catch (err) {
      setAuthError("Database error occurred.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickUnlock = async (id: string) => {
    setLoginId(id);
    setIsLoading(true);
    try {
      const found = await dbService.getRecord(id);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, id);
        setIsAuth(true);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
  };

  const initiatePaymentVerification = async () => {
    if (selectedMethod === 'upi') {
      const amount = PLANS[selectedPlan].price;
      const upiLink = `upi://pay?pa=shakeelmohamed082@oksbi&pn=Shakeel Mohamed&am=${amount}&cu=INR`;
      window.location.href = upiLink;

      // We still simulate the "verifying" state after redirecting for a premium feel
      setPaymentStep('verifying');
    } else {
      setPaymentStep('verifying');
    }

    const steps = [
      "Initializing Secure Protocol...",
      "Requesting Signature...",
      "Authenticating Clinical Identity...",
      "Finalizing Vault Encryption..."
    ];

    for (const step of steps) {
      setVerificationSubStep(step);
      await new Promise(r => setTimeout(r, 1200));
    }

    if (!currentUser) return;
    const expiry = new Date();
    expiry.setFullYear(expiry.getFullYear() + 1);

    const updatedUser: HealthRecord = {
      ...currentUser,
      profile: { 
        ...currentUser.profile, 
        isPremium: true, 
        subscriptionPlan: selectedPlan,
        subscriptionExpiry: expiry.toISOString() 
      }
    };

    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setPaymentStep('success');
    } catch (err) {
      alert("Verification failed.");
      setPaymentStep('summary');
    }
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: [...collection, { ...item, id: Date.now().toString() }]
    };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
    setShowAddModal(null);
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.filter((item: any) => item.id !== itemId)
    };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    const currentQ = userQuery;
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, currentQ);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);

      const newInteraction: Interaction = { id: Date.now().toString(), query: currentQ, response, timestamp: Date.now() };
      const updatedUser = {
        ...currentUser,
        interactions: [newInteraction, ...(currentUser.interactions || [])]
      };
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } finally {
      setIsAiLoading(false);
    }
  };

  const filteredSearchResults = useMemo(() => {
    if (!currentUser || !globalSearchTerm.trim()) return null;
    const term = globalSearchTerm.toLowerCase();
    return {
      problems: (currentUser.problems || []).filter(p => p.condition.toLowerCase().includes(term)),
      medications: (currentUser.medications || []).filter(m => m.name.toLowerCase().includes(term)),
      allergies: (currentUser.allergies || []).filter(a => a.substance.toLowerCase().includes(term)),
      surgeries: (currentUser.surgeries || []).filter(s => s.type.toLowerCase().includes(term)),
      notes: (currentUser.notes || []).filter(n => n.doctorName.toLowerCase().includes(term) || n.note.toLowerCase().includes(term))
    };
  }, [currentUser, globalSearchTerm]);

  const foundPatients = useMemo(() => {
    if (!patientLookupTerm.trim()) return [];
    const term = patientLookupTerm.toUpperCase();
    return allPatients.filter(p => p.profile.healthId.includes(term));
  }, [allPatients, patientLookupTerm]);

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-indigo-300 font-bold uppercase tracking-widest text-xs font-mono">Decrypting Local Vault...</p>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4">
        <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-12 bg-white rounded-[3rem] auth-card overflow-hidden">
          <div className="lg:col-span-5 bg-indigo-950 p-12 text-white flex flex-col justify-between relative">
            <div className="relative z-10">
              <div className="flex items-center gap-4 mb-12">
                <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-indigo-950 text-2xl">{ICONS.LOCK}</div>
                <h1 className="text-xl font-black uppercase italic tracking-tighter">{APP_NAME}</h1>
              </div>
              <h2 className="text-5xl font-black leading-tight tracking-tighter">Secure <br/><span className="text-indigo-400">Clinical</span> Vault.</h2>
              <p className="mt-6 text-indigo-200/60 leading-relaxed font-medium">Your medical identity stays on your device. We never store clinical history on our servers.</p>
            </div>
          </div>
          <div className="lg:col-span-7 p-12 bg-slate-50/50 flex flex-col justify-center">
             {showRegSuccess ? (
                <div className="text-center animate-pop-in">
                  <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-3xl flex items-center justify-center text-4xl mx-auto mb-6">{ICONS.SHIELD_CHECK}</div>
                  <h3 className="text-2xl font-black mb-2">Registration Complete</h3>
                  <p className="text-slate-500 mb-8">Save your Health ID securely. It is the only key to your vault.</p>
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 mb-8">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Your 6-Digit Health ID</p>
                    <p className="text-4xl font-mono font-black text-indigo-600 tracking-wider">{showRegSuccess}</p>
                  </div>
                  <button onClick={completeRegistration} className="w-full bg-indigo-600 text-white font-black py-5 rounded-3xl shadow-xl hover:bg-indigo-700 transition-all">Open Vault</button>
                </div>
             ) : (
                <div className="max-w-md mx-auto w-full">
                  <div className="flex bg-slate-200 p-1 rounded-2xl mb-10">
                    <button onClick={() => setAuthMode('login')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${authMode === 'login' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>Login</button>
                    <button onClick={() => setAuthMode('register')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${authMode === 'register' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500'}`}>Sign Up</button>
                  </div>
                  <form onSubmit={authMode === 'login' ? handleLogin : handleRegister} className="space-y-6 animate-slide-in">
                    {authMode === 'register' && (
                      <>
                        <input required name="name" placeholder="Full Legal Name" className="w-full p-4 rounded-2xl border border-slate-200 bg-white outline-none focus:border-indigo-500" />
                        <div className="grid grid-cols-2 gap-4">
                          <input required name="age" type="number" placeholder="Age" className="w-full p-4 rounded-2xl border border-slate-200 bg-white outline-none" />
                          <select name="bloodGroup" className="w-full p-4 rounded-2xl border border-slate-200 bg-white outline-none">
                            <option value="">Blood Group</option>
                            {['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                          </select>
                        </div>
                      </>
                    )}
                    <input 
                        value={loginId} 
                        onChange={(e) => setLoginId(e.target.value.toUpperCase())} 
                        placeholder={authMode === 'login' ? "Health ID (HID-XXXXXX)" : "Optional Pre-filled ID"} 
                        className="w-full p-4 rounded-2xl border border-slate-200 bg-white font-mono uppercase outline-none focus:border-indigo-500" 
                    />
                    <button type="submit" className="w-full bg-indigo-950 text-white font-black py-5 rounded-3xl shadow-xl hover:bg-indigo-900 transition-all uppercase tracking-widest">{authMode === 'login' ? 'Unlock Vault' : 'Create Vault'}</button>
                  </form>
                </div>
             )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout} isPremium={currentUser?.profile?.isPremium}>
      {activeTab === 'dashboard' ? (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className={`lg:col-span-2 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden ${currentUser?.profile?.isPremium ? 'bg-slate-900' : 'bg-indigo-600'}`}>
              <div className="relative z-10">
                <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-8">Clinical Identity Passport</p>
                <h1 className="text-5xl font-mono font-black mb-12 tracking-wider">{currentUser?.profile?.healthId}</h1>
                <div className="grid grid-cols-3 gap-8">
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Blood Group</p><p className="font-black text-2xl">{currentUser?.profile?.bloodGroup}</p></div>
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Age</p><p className="font-black text-2xl">{currentUser?.profile?.age}</p></div>
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Vault Status</p><p className="font-black text-sm uppercase tracking-widest text-emerald-400">Encrypted</p></div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-[2.5rem] p-10 shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-3xl mb-4">{ICONS.SHIELD_CHECK}</div>
              <p className="font-black text-emerald-600 italic">256-bit AES Active</p>
              <p className="text-[10px] text-slate-400 mt-2 font-medium">Data is isolated on your local storage.</p>
            </div>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {[
              { label: 'Conditions', val: (currentUser?.problems || []).length, icon: ICONS.MEDICAL },
              { label: 'Medications', val: (currentUser?.medications || []).length, icon: ICONS.MEDS },
              { label: 'Surgeries', val: (currentUser?.surgeries || []).length, icon: ICONS.SURGERY },
              { label: 'Allergies', val: (currentUser?.allergies || []).length, icon: ICONS.ALLERGY },
            ].map((s, i) => (
              <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-6 group hover:border-indigo-100 hover:shadow-lg transition-all">
                <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-2xl group-hover:bg-indigo-600 group-hover:text-white transition-all">{s.icon}</div>
                <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{s.label}</p><p className="text-2xl font-black text-slate-800">{s.val}</p></div>
              </div>
            ))}
          </div>
        </div>
      ) : activeTab === 'records' ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pb-32">
          <RecordCard title="Medical History" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
            <div className="space-y-4">
              {(currentUser?.problems || []).map(p => (
                <div key={p.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center group">
                  <div>
                    <h4 className="font-black text-slate-800">{p.condition}</h4>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Since {p.onsetDate}</p>
                  </div>
                  <button onClick={() => removeMedicalItem('problems', p.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><i className="fas fa-trash-alt"></i></button>
                </div>
              ))}
            </div>
          </RecordCard>
          <RecordCard title="Active Meds" icon={ICONS.MEDS} onAdd={() => setShowAddModal('medication')}>
             <div className="space-y-4">
              {(currentUser?.medications || []).map(m => (
                <div key={m.id} className="p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100/30 flex justify-between items-center group">
                  <div>
                    <h4 className="font-black text-indigo-700">{m.name}</h4>
                    <p className="text-[10px] text-indigo-400 font-bold uppercase mt-1">{m.dosage} • {m.frequency}</p>
                  </div>
                  <button onClick={() => removeMedicalItem('medications', m.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><i className="fas fa-trash-alt"></i></button>
                </div>
              ))}
            </div>
          </RecordCard>
        </div>
      ) : activeTab === 'subscription' ? (
        <div className="pb-32">
          <div className="max-w-4xl mx-auto space-y-12">
            <div className="text-center space-y-4">
              <h2 className="text-4xl font-black tracking-tight text-slate-800">Secure Your Clinical Data</h2>
              <p className="text-slate-500 font-medium max-w-xl mx-auto leading-relaxed text-sm">Upgrade to our premium tiers for end-to-end device synchronization and priority August AI analysis.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Pro Plan */}
              <div className={`p-10 rounded-[3rem] border-2 transition-all relative overflow-hidden flex flex-col cursor-pointer ${selectedPlan === 'pro' ? 'border-indigo-600 bg-white shadow-2xl scale-[1.02]' : 'border-slate-100 bg-slate-50 opacity-80'}`} onClick={() => setSelectedPlan('pro')}>
                {selectedPlan === 'pro' && <div className="absolute top-6 right-6 text-indigo-600 text-2xl">{ICONS.CHECK}</div>}
                <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl mb-8">
                  <i className="fas fa-bolt"></i>
                </div>
                <h3 className="text-2xl font-black mb-2">{PLANS.pro.name}</h3>
                <div className="flex items-baseline gap-2 mb-8">
                  <span className="text-4xl font-black">₹{PLANS.pro.price}</span>
                  <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">/ Month</span>
                </div>
                <ul className="space-y-4 mb-12 flex-grow">
                  {PLANS.pro.features.map(f => (
                    <li key={f} className="flex items-center gap-3 text-sm font-medium text-slate-600">
                      <i className="fas fa-check text-emerald-500"></i> {f}
                    </li>
                  ))}
                </ul>
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowPaymentModal(true); setPaymentStep('summary'); }} 
                  className={`w-full py-5 rounded-3xl font-black uppercase tracking-widest text-xs transition-all ${selectedPlan === 'pro' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white text-indigo-600 border border-indigo-100'}`}
                >
