                    <div className="flex justify-between items-center"><span className="text-xs font-bold text-slate-500 uppercase">Selected Plan</span><span className="font-black text-slate-800">{PLANS[selectedPlan].name}</span></div>
                    <div className="flex justify-between items-center"><span className="text-xs font-bold text-slate-500 uppercase">Vault Expansion</span><span className="font-black text-slate-800">12 Months</span></div>
                    <div className="pt-4 border-t border-slate-200 flex justify-between items-center">
                      <span className="text-sm font-black text-slate-800 uppercase">Total to Pay</span>
                      <span className="text-3xl font-black text-indigo-600">₹{PLANS[selectedPlan].price}</span>
                    </div>
                 </div>
                 <div className="space-y-4">
                    <button onClick={() => setPaymentStep('method')} className="w-full py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 transition-all uppercase tracking-widest text-sm">Proceed to Payment</button>
                    <p className="text-center text-[10px] text-slate-400 font-bold uppercase flex items-center justify-center gap-2"><i className="fas fa-shield-alt"></i> Clinical encryption standards applied • SSL Secured</p>
                 </div>
               </div>
             )}

             {paymentStep === 'method' && (
               <div className="space-y-8 animate-slide-in">
                 <div className="grid grid-cols-1 gap-4">
                    {[
                      { id: 'upi', label: 'UPI Smart Pay', icon: ICONS.UPI, desc: 'PhonePe, GPay, Paytm, BHIM' },
                      { id: 'card', label: 'Credit / Debit Card', icon: ICONS.CREDIT_CARD, desc: 'Visa, Mastercard, RuPay' },
                      { id: 'bank', label: 'Direct Net Banking', icon: ICONS.BANK, desc: 'Login via your bank gateway' }
                    ].map(method => (
                      <button 
                        key={method.id} 
                        onClick={() => setSelectedMethod(method.id as any)}
                        className={`p-6 rounded-[2rem] border-2 text-left flex items-center gap-5 transition-all ${selectedMethod === method.id ? 'border-indigo-600 bg-indigo-50/50' : 'border-slate-100 hover:border-slate-200'}`}
                      >
                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-xl ${selectedMethod === method.id ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-500'}`}>{method.icon}</div>
                        <div><p className="font-black text-slate-800">{method.label}</p><p className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">{method.desc}</p></div>
                        {selectedMethod === method.id && <div className="ml-auto text-indigo-600 text-xl"><i className="fas fa-check-circle"></i></div>}
                      </button>
                    ))}
                 </div>
                 <div className="flex gap-4">
                    <button onClick={() => setPaymentStep('summary')} className="flex-1 py-5 bg-slate-100 text-slate-500 font-black rounded-3xl uppercase text-[10px]">Back</button>
                    <button onClick={initiatePaymentVerification} className="flex-[2] py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">
                      {selectedMethod === 'upi' ? 'Pay Securely via UPI' : 'Verify & Pay'}
                    </button>
                 </div>
               </div>
             )}

             {paymentStep === 'verifying' && (
               <div className="py-20 text-center space-y-10 animate-pop-in">
                 <div className="relative mx-auto w-32 h-32">
                    <div className="absolute inset-0 border-8 border-indigo-100 rounded-full"></div>
                    <div className="absolute inset-0 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                    <div className="absolute inset-0 flex items-center justify-center text-3xl text-indigo-600">
                      <i className="fas fa-shield-virus animate-pulse"></i>
                    </div>
                 </div>
                 <div className="space-y-3">
                    <p className="text-2xl font-black text-slate-800 tracking-tight">{verificationSubStep}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em]">Encrypted Session Active</p>
                 </div>
                 <div className="bg-indigo-50 p-4 rounded-2xl flex items-center justify-center gap-3 text-[10px] font-black text-indigo-600 uppercase">
                    <span className="w-2 h-2 bg-indigo-500 rounded-full animate-ping"></span>
                    Secure Handshake Protocol
                 </div>
               </div>
             )}

             {paymentStep === 'success' && (
               <div className="py-10 text-center space-y-10 animate-pop-in">
                 <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2.5rem] flex items-center justify-center text-5xl mx-auto shadow-2xl border border-emerald-100">{ICONS.SHIELD_CHECK}</div>
                 <div>
                    <h3 className="text-3xl font-black mb-2 tracking-tight">Payment Verified</h3>
                    <p className="text-slate-500 font-medium px-8 text-sm leading-relaxed">Vault successfully upgraded to <span className="text-indigo-600 font-bold">{PLANS[selectedPlan].name}</span>.</p>
                 </div>
                 <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 text-left space-y-4">
                    <div className="flex justify-between text-[10px] font-bold text-slate-400 uppercase"><span>Transaction ID</span><span className="font-mono text-slate-800 uppercase tracking-wider">HS-{Math.random().toString(36).substring(2, 10).toUpperCase()}</span></div>
                    <div className="flex justify-between text-[10px] font-bold text-slate-400 uppercase"><span>Active Vault</span><span className="text-slate-800">{PLANS[selectedPlan].name}</span></div>
                    <div className="flex justify-between text-[10px] font-bold text-slate-400 uppercase"><span>Validity</span><span className="text-slate-800">12 Months</span></div>
                 </div>
                 <button onClick={() => { setShowPaymentModal(false); setActiveTab('dashboard'); }} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl hover:bg-indigo-700 uppercase tracking-widest text-xs">Access Premium Vault</button>
               </div>
             )}
          </div>
        </div>
      )}

      {/* Add Record Modals */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xl">
          <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl animate-pop-in max-h-[90vh] overflow-y-auto custom-scrollbar border border-slate-200">
            <div className="flex items-center gap-4 mb-10">
                <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">
                    {showAddModal === 'problem' ? ICONS.MEDICAL : 
                     showAddModal === 'medication' ? ICONS.MEDS :
                     showAddModal === 'allergy' ? ICONS.ALLERGY :
                     showAddModal === 'surgery' ? ICONS.SURGERY : ICONS.NOTE}
                </div>
                <h3 className="text-2xl font-black tracking-tight capitalize">New {showAddModal} Entry</h3>
            </div>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), severity: f.get('severity'), onsetDate: f.get('date'), status: 'present', notes: f.get('notes') });
              if (showAddModal === 'medication') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), frequency: f.get('freq'), duration: f.get('duration') });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity'), reaction: f.get('reaction') });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital') });
              if (showAddModal === 'note') addMedicalItem('notes', { doctorName: f.get('doc'), date: f.get('date'), note: f.get('note'), clinicName: f.get('clinic') });
            }} className="space-y-5">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  <div className="grid grid-cols-2 gap-4">
                    <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px] tracking-widest">
                      <option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option>
                    </select>
                    <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  </div>
                  <textarea name="notes" placeholder="Symptoms or diagnostic notes..." className="w-full p-6 bg-slate-50 border border-slate-200 rounded-3xl h-32 outline-none text-sm"></textarea>
                </>
              )}
              {showAddModal === 'medication' && (
                <>
                  <input required name="name" placeholder="Medication Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  <div className="grid grid-cols-2 gap-4">
                    <input required name="dosage" placeholder="Dosage" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                    <input required name="freq" placeholder="Frequency" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  </div>
                </>
              )}
              {showAddModal === 'allergy' && (
                <>
                  <input required name="substance" placeholder="Allergen" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px]">
                    <option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option>
                  </select>
                </>
              )}
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 bg-slate-100 rounded-3xl font-black uppercase tracking-widest text-[10px]">Discard</button>
                <button type="submit" className="flex-1 py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl uppercase tracking-widest text-[10px]">Commit</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

export interface UserProfile {
  name: string;
  age: number;
  dob: string;
  gender: string;
  phone: string;
  aadhaar: string;
  healthId: string;
  bloodGroup: string;
  isPremium?: boolean;
  subscriptionPlan?: 'standard' | 'pro' | 'family';
  subscriptionExpiry?: string;
}

export interface MedicalProblem {
  id: string;
  condition: string;
  status: 'past' | 'present' | 'recovered';
  onsetDate: string;
  endDate?: string;
  severity: 'mild' | 'moderate' | 'severe';
  treatment?: string;
  notes?: string;
}

export interface Medication {
  id: string;
  name: string;
  dosage: string;
  duration: string;
  frequency: string;
  startDate: string;
  instructions?: string;
  prescribedBy?: string;
  status: 'active' | 'discontinued';
}

export interface Surgery {
  id: string;
  type: string;
  date: string;
  hospital: string;
  surgeon?: string;
  outcome?: string;
}

export interface Allergy {
  id: string;
  substance: string;
  severity: 'low' | 'moderate' | 'high';
  reaction?: string;
  firstObserved?: string;
}

export interface TreatmentNote {
  id: string;
  doctorName: string;
  date: string;
  note: string;
  clinicName?: string;
  category?: 'Consultation' | 'Follow-up' | 'Emergency' | 'Surgery';
}

export interface Interaction {
  id: string;
  query: string;
  response: string;
  timestamp: number;
}

export interface HealthRecord {
  profile: UserProfile;
  problems: MedicalProblem[];
  medications: Medication[];
  surgeries: Surgery[];
  allergies: Allergy[];
  notes: TreatmentNote[];
  interactions?: Interaction[];
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, HealthRecord, ChatMessage, Interaction, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote } from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;
type PaymentStep = 'summary' | 'method' | 'verifying' | 'success';
type PlanType = 'pro' | 'family';

const PLANS = {
  pro: { name: 'Pro Vault', price: 99, features: ['Unlimited August AI', 'E2E Sync', 'Clinical Priority'] },
  family: { name: 'Family Shield', price: 299, features: ['Up to 4 Users', 'Biometric Lock', '24/7 Support'] }
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allPatients, setAllPatients] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isScanning, setIsScanning] = useState(false);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [globalSearchTerm, setGlobalSearchTerm] = useState('');
  const [patientLookupTerm, setPatientLookupTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentStep, setPaymentStep] = useState<PaymentStep>('summary');
  const [selectedPlan, setSelectedPlan] = useState<PlanType>('pro');
  const [selectedMethod, setSelectedMethod] = useState<'card' | 'upi' | 'bank'>('upi');
  const [verificationSubStep, setVerificationSubStep] = useState('');

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
        const records = await dbService.getAllRecords();
        setAllPatients(records);
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    bootstrap();
  }, [isAuth]);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsScanning(true);

    const formData = new FormData(e.currentTarget);
    const randomCode = Math.random().toString(36).substring(2, 8).toUpperCase();
    const healthId = `HID-${randomCode}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      healthId,
      isPremium: false,
      subscriptionPlan: 'standard'
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], interactions: []
    };

    try {
      await new Promise(r => setTimeout(r, 2000));
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Vault initialization failed. Storage full?");
    } finally {
      setIsScanning(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsScanning(true);
    const inputId = (loginId || '').trim().toUpperCase();

    try {
      await new Promise(r => setTimeout(r, 1500));
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Identity key not recognized. Access denied.");
      }
    } catch (err) {
      setAuthError("Vault synchronization error.");
    } finally {
      setIsScanning(false);
    }
  };

  const handleQuickUnlock = async (id: string) => {
    setLoginId(id);
    setAuthError('');
    setIsScanning(true);
    try {
      await new Promise(r => setTimeout(r, 1000));
      const found = await dbService.getRecord(id);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, id);
        setIsAuth(true);
      }
    } finally {
      setIsScanning(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  const initiatePaymentVerification = async () => {
    if (selectedMethod === 'upi') {
      const amount = PLANS[selectedPlan].price;
      const upiLink = `upi://pay?pa=shakeelmohamed082@oksbi&pn=Shakeel Mohamed&am=${amount}&cu=INR`;
      window.location.href = upiLink;
      setPaymentStep('verifying');
    } else {
      setPaymentStep('verifying');
    }

    const steps = ["Initializing Secure Protocol...", "Requesting Signature...", "Authenticating Clinical Identity...", "Finalizing Vault Encryption..."];
    for (const step of steps) {
      setVerificationSubStep(step);
      await new Promise(r => setTimeout(r, 1200));
    }

    if (!currentUser) return;
    const expiry = new Date();
    expiry.setFullYear(expiry.getFullYear() + 1);

    const updatedUser: HealthRecord = {
      ...currentUser,
      profile: { ...currentUser.profile, isPremium: true, subscriptionPlan: selectedPlan, subscriptionExpiry: expiry.toISOString() }
    };

    try {
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
      setPaymentStep('success');
    } catch (err) {
      alert("Verification failed.");
      setPaymentStep('summary');
    }
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = { ...currentUser, [type]: [...collection, { ...item, id: Date.now().toString() }] };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
    setShowAddModal(null);
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently from the local vault?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = { ...currentUser, [type]: collection.filter((item: any) => item.id !== itemId) };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
  };

  const updateMedicalItemStatus = async (type: keyof HealthRecord, itemId: string, newStatus: string) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.map((item: any) => item.id === itemId ? { ...item, status: newStatus } : item)
    };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    const currentQ = userQuery;
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, currentQ);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);

      const newInteraction: Interaction = { id: Date.now().toString(), query: currentQ, response, timestamp: Date.now() };
      const updatedUser = { ...currentUser, interactions: [newInteraction, ...(currentUser.interactions || [])] };
      await dbService.saveRecord(updatedUser);
      setCurrentUser(updatedUser);
    } finally {
      setIsAiLoading(false);
    }
  };

  const filteredSearchResults = useMemo(() => {
    if (!currentUser || !globalSearchTerm.trim()) return null;
    const term = globalSearchTerm.toLowerCase();
    return {
      problems: (currentUser.problems || []).filter(p => p.condition.toLowerCase().includes(term)),
      medications: (currentUser.medications || []).filter(m => m.name.toLowerCase().includes(term)),
      allergies: (currentUser.allergies || []).filter(a => a.substance.toLowerCase().includes(term)),
      surgeries: (currentUser.surgeries || []).filter(s => s.type.toLowerCase().includes(term)),
      notes: (currentUser.notes || []).filter(n => n.doctorName.toLowerCase().includes(term) || n.note.toLowerCase().includes(term))
    };
  }, [currentUser, globalSearchTerm]);

  const foundPatients = useMemo(() => {
    if (!patientLookupTerm.trim()) return [];
    const term = patientLookupTerm.toUpperCase();
    return allPatients.filter(p => p.profile.healthId.includes(term));
  }, [allPatients, patientLookupTerm]);

  // Record Severity Styles
  const getSeverityStyle = (severity: string) => {
    switch (severity.toLowerCase()) {
      case 'severe': case 'high': return 'bg-rose-50 text-rose-700 border-rose-100';
      case 'moderate': return 'bg-amber-50 text-amber-700 border-amber-100';
      case 'mild': case 'low': return 'bg-emerald-50 text-emerald-700 border-emerald-100';
      default: return 'bg-slate-50 text-slate-700 border-slate-100';
    }
  };

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center relative overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500/10 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 rounded-full blur-[120px]"></div>
        <div className="text-center relative z-10">
          <div className="w-20 h-20 bg-indigo-600/20 rounded-3xl flex items-center justify-center text-indigo-400 text-3xl mx-auto mb-6 border border-indigo-500/30 pulse-glow">
            <i className="fas fa-shield-virus"></i>
          </div>
          <p className="text-indigo-300 font-bold uppercase tracking-[0.3em] text-[10px] animate-pulse">Initializing Secure Environment</p>
        </div>
      </div>
