          <div className="lg:col-span-5 bg-indigo-950 p-12 text-white flex flex-col justify-between relative border-r border-white/5">
            <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-10">
              <i className="fas fa-microchip text-[300px] absolute -bottom-20 -left-20 rotate-12"></i>
            </div>

            <div className="relative z-10">
              <div className="flex items-center gap-4 mb-16">
                <div className="w-14 h-14 bg-indigo-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-[0_0_30px_-5px_rgba(99,102,241,0.5)]">
                  {ICONS.LOCK}
                </div>
                <div>
                  <h1 className="text-2xl font-black uppercase tracking-tighter italic">{APP_NAME}</h1>
                  <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest">Local-First Medical Identity</p>
                </div>
              </div>

              <div className="space-y-8">
                <h2 className="text-6xl font-black leading-[0.9] tracking-tighter">
                  Your <span className="text-indigo-400">Vault</span>,<br/>
                  Your <span className="text-indigo-400">Rules</span>.
                </h2>
                <p className="text-lg text-indigo-200/70 font-medium leading-relaxed max-w-sm">
                  The first medical record system where data never leaves your device unless you choose to share it.
                </p>
              </div>
            </div>

            <div className="relative z-10 space-y-4">
              <div className="flex items-center gap-4 p-4 rounded-2xl bg-white/5 border border-white/10 backdrop-blur-md">
                <div className="w-10 h-10 rounded-xl bg-emerald-500/20 text-emerald-400 flex items-center justify-center">
                  <i className="fas fa-check-shield"></i>
                </div>
                <div>
                  <p className="text-xs font-black uppercase tracking-widest text-white">Device Isolated</p>
                  <p className="text-[10px] text-indigo-300 font-medium">Data resides in IndexedDB locally.</p>
                </div>
              </div>
              <div className="flex items-center gap-4 p-4 rounded-2xl bg-white/5 border border-white/10 backdrop-blur-md">
                <div className="w-10 h-10 rounded-xl bg-indigo-500/20 text-indigo-400 flex items-center justify-center">
                  <i className="fas fa-fingerprint"></i>
                </div>
                <div>
                  <p className="text-xs font-black uppercase tracking-widest text-white">Secure Identity</p>
                  <p className="text-[10px] text-indigo-300 font-medium">Unique 6-digit HID key generation.</p>
                </div>
              </div>
            </div>
          </div>

          <div className="lg:col-span-7 bg-slate-50 p-12 lg:p-20 flex flex-col justify-center relative">
            {isScanning && (
              <div className="absolute inset-0 z-50 bg-slate-50/80 backdrop-blur-md flex flex-col items-center justify-center text-center">
                <div className="w-24 h-24 relative mb-8">
                  <div className="absolute inset-0 border-4 border-indigo-100 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                  <div className="absolute inset-0 flex items-center justify-center text-3xl text-indigo-600">
                    <i className="fas fa-user-shield animate-pulse"></i>
                  </div>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight mb-2">Authenticating Profile</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Checking secure local storage...</p>
              </div>
            )}

            {showRegSuccess ? (
              <div className="max-w-md mx-auto w-full text-center animate-pop-in">
                <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-[2rem] flex items-center justify-center text-5xl mx-auto mb-8 shadow-xl">
                  <i className="fas fa-id-badge"></i>
                </div>
                <h3 className="text-4xl font-black text-slate-800 tracking-tight mb-4">Vault Created</h3>
                <p className="text-slate-500 font-medium mb-10 leading-relaxed">Save this key in a safe place. This is your <span className="text-indigo-600 font-bold uppercase">only</span> access to your local medical history.</p>

                <div className="bg-white p-10 rounded-[3rem] border-2 border-dashed border-indigo-200 mb-10 group relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform">
                    <i className="fas fa-key text-6xl"></i>
                  </div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Identity Health ID</p>
                  <p className="text-5xl font-mono font-black text-indigo-600 tracking-widest">{showRegSuccess}</p>
                </div>

                <button onClick={completeRegistration} className="w-full py-6 bg-slate-900 text-white font-black rounded-[2rem] shadow-2xl hover:bg-indigo-600 transition-all uppercase tracking-widest text-lg flex items-center justify-center gap-4 group">
                  Unlock My Vault <i className="fas fa-arrow-right group-hover:translate-x-2 transition-transform"></i>
                </button>
              </div>
            ) : (
              <div className="max-w-md mx-auto w-full">
                <div className="relative bg-slate-200 p-1.5 rounded-[2.2rem] flex mb-16 shadow-inner border border-slate-300/30">
                  <div className={`absolute top-1.5 bottom-1.5 left-1.5 w-[calc(50%-6px)] bg-white rounded-[1.8rem] shadow-xl transition-all duration-500 ease-out ${authMode === 'register' ? 'translate-x-[calc(100%+6px)]' : 'translate-x-0'}`}></div>
                  <button onClick={() => setAuthMode('login')} className={`relative z-10 flex-1 py-4 text-[11px] font-black uppercase tracking-widest transition-all ${authMode === 'login' ? 'text-indigo-600' : 'text-slate-500'}`}>Existing User</button>
                  <button onClick={() => setAuthMode('register')} className={`relative z-10 flex-1 py-4 text-[11px] font-black uppercase tracking-widest transition-all ${authMode === 'register' ? 'text-indigo-600' : 'text-slate-500'}`}>New Patient</button>
                </div>

                {authError && (
                  <div className="mb-8 p-5 bg-rose-50 border border-rose-100 text-rose-600 rounded-[2rem] text-xs font-bold flex items-center gap-4 animate-slide-in">
                    <i className="fas fa-exclamation-triangle text-xl"></i>
                    {authError}
