                )}

                {authMode === 'login' ? (
                  <div className="space-y-10 animate-slide-in">
                    <form onSubmit={handleLogin} className="space-y-6">
                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Identity Access Key</label>
                        <div className="relative group">
                          <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-slate-400 group-focus-within:text-indigo-600 transition-colors">
                            <i className="fas fa-key text-xl"></i>
                          </div>
                          <input 
                            required
                            value={loginId} 
                            onChange={(e) => setLoginId(e.target.value.toUpperCase())} 
                            placeholder="HID-XXXXXX"
                            className="w-full pl-16 pr-8 py-6 rounded-[2.2rem] bg-white border border-slate-200 text-2xl font-mono uppercase focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 outline-none transition-all shadow-sm"
                          />
                        </div>
                      </div>
                      <button type="submit" className="w-full bg-indigo-600 text-white font-black py-6 rounded-[2.2rem] text-lg hover:bg-indigo-700 shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-3">
                        Secure Login <i className="fas fa-unlock"></i>
                      </button>
                    </form>

                    {lastHid && (
                      <div className="pt-10 border-t border-slate-200">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center mb-6">Quick Unlock Previous Session</p>
                        <button 
                          onClick={() => handleQuickUnlock(lastHid)} 
                          className="w-full p-6 bg-white border border-slate-200 hover:border-indigo-400 rounded-3xl flex items-center justify-between group transition-all hover:shadow-xl hover:-translate-y-1"
                        >
                          <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-xl group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                              <i className="fas fa-fingerprint"></i>
                            </div>
                            <div className="text-left">
                              <p className="text-sm font-black text-slate-800">Local Vault Active</p>
                              <p className="text-[10px] font-mono text-slate-400">{lastHid}</p>
                            </div>
                          </div>
                          <i className="fas fa-chevron-right text-slate-300 group-hover:text-indigo-600 transition-colors"></i>
                        </button>
                      </div>
                    )}
                  </div>
                ) : (
                  <form onSubmit={handleRegister} className="space-y-6 animate-slide-in max-h-[480px] overflow-y-auto pr-2 custom-scrollbar pb-6">
                    <div className="space-y-4">
                      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-5">
                        <div className="flex items-center gap-4 pb-4 border-b border-slate-50">
                          <div className="w-10 h-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-lg"><i className="fas fa-user"></i></div>
                          <p className="text-xs font-black uppercase tracking-widest text-slate-800">Basic Profile</p>
                        </div>
                        <input required name="name" placeholder="Full Legal Name" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 focus:bg-white focus:border-indigo-400 outline-none transition-all text-sm font-medium" />
                        <div className="grid grid-cols-2 gap-4">
                          <input required name="age" type="number" placeholder="Age" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-medium" />
                          <select required name="bloodGroup" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-bold uppercase tracking-widest">
                            <option value="">Blood Group</option>
                            {['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                          </select>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <select required name="gender" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-bold uppercase">
                            <option value="Male">Male</option>
                            <option value="Female">Female</option>
                            <option value="Other">Other</option>
                          </select>
                          <input required name="phone" placeholder="Contact Phone" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-medium" />
                        </div>
                        <input required name="aadhaar" pattern="\d{12}" placeholder="Aadhaar Number (12 Digits)" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-medium" />
                        <div className="space-y-2">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Date of Birth</label>
                          <input required name="dob" type="date" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-medium" />
                        </div>
                      </div>
                    </div>
                    <button type="submit" className="w-full bg-emerald-600 text-white font-black py-6 rounded-[2.5rem] shadow-xl shadow-emerald-500/20 hover:bg-emerald-700 transition-all uppercase tracking-widest flex items-center justify-center gap-3">
                      Initialize Vault <i className="fas fa-shield-plus"></i>
                    </button>
                  </form>
                )}

                <div className="mt-12 flex justify-center items-center gap-8 opacity-40 grayscale pointer-events-none">
                  <div className="flex items-center gap-2 text-[9px] font-black uppercase"><i className="fas fa-lock text-xs"></i> 256-Bit</div>
                  <div className="flex items-center gap-2 text-[9px] font-black uppercase"><i className="fas fa-server text-xs"></i> Zero-Cloud</div>
                  <div className="flex items-center gap-2 text-[9px] font-black uppercase"><i className="fas fa-user-check text-xs"></i> Verified</div>
                </div>
              </div>
            )}
          </div>
        </div>
        <p className="fixed bottom-8 text-center w-full text-slate-500 text-[10px] font-bold uppercase tracking-[0.4em] opacity-40 pointer-events-none">AES-256 Bit Physical Device Isolation Active</p>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout} isPremium={currentUser?.profile?.isPremium}>
      {activeTab === 'dashboard' ? (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className={`lg:col-span-2 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden ${currentUser?.profile?.isPremium ? 'bg-slate-900' : 'bg-indigo-600'}`}>
              <div className="relative z-10">
                <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-8">Clinical Identity Passport</p>
                <h1 className="text-5xl font-mono font-black mb-12 tracking-wider">{currentUser?.profile?.healthId}</h1>
