import { GoogleGenAI } from "@google/genai";
import { HealthRecord } from "../types";

export const analyzeHealthRecord = async (record: HealthRecord, query: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are August AI, a professional medical records assistant. 
    Analyze the provided health history for this user: ${JSON.stringify(record)}.

    Guidelines:
    1. Always include a disclaimer: "I am August AI, a guidance assistant. I am not a substitute for professional medical advice, diagnosis, or treatment. Always seek the advice of your physician."
    2. Deeply analyze the user's Blood Group (${record.profile.bloodGroup}), Allergies, and current Medications.
    3. Look for potential drug-drug interactions or conflicts between their conditions.
    4. MANDATORY: For any chronic or serious medical condition listed (e.g., Cancer, Heart issues, Kidney disease, Tuberculosis), search for and suggest relevant Indian Government Health Schemes (e.g., Ayushman Bharat (PM-JAY), RSBY, State-specific schemes like CMCHIS). 
    5. Explain eligibility for these schemes based on their Age (${record.profile.age}) and condition severity.
    6. Provide specific lifestyle advice tailored to their profile.
    7. Be professional and empathetic. Mask sensitive IDs.

    Context:
    Name: ${record.profile.name}
    Health ID: ${record.profile.healthId}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: query,
      config: {
        systemInstruction,
        temperature: 0.6,
        thinkingConfig: { thinkingBudget: 8000 }
      },
    });

    return response.text || "I'm sorry, I couldn't process your request.";
  } catch (error) {
    console.error("Gemini AI error:", error);
    return "I encountered an error while analyzing your health data. Please try again later.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, HealthRecord, ChatMessage, Interaction, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, GovernmentScheme } from './types';
