const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;
type PaymentStep = 'summary' | 'method' | 'verifying' | 'success';
type PlanType = 'pro' | 'family';

const PLANS = {
  pro: { name: 'Pro Vault', price: 99, features: ['Unlimited August AI', 'E2E Sync', 'Clinical Priority'] },
  family: { name: 'Family Shield', price: 299, features: ['Up to 4 Users', 'Biometric Lock', '24/7 Support'] }
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allPatients, setAllPatients] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isScanning, setIsScanning] = useState(false);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [globalSearchTerm, setGlobalSearchTerm] = useState('');
  const [patientLookupTerm, setPatientLookupTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentStep, setPaymentStep] = useState<PaymentStep>('summary');
  const [selectedPlan, setSelectedPlan] = useState<PlanType>('pro');
  const [selectedMethod, setSelectedMethod] = useState<'card' | 'upi' | 'bank'>('upi');
  const [verificationSubStep, setVerificationSubStep] = useState('');

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
        const records = await dbService.getAllRecords();
        setAllPatients(records);
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    bootstrap();
  }, [isAuth]);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsScanning(true);

    const formData = new FormData(e.currentTarget);
    const randomCode = Math.random().toString(36).substring(2, 8).toUpperCase();
    const healthId = `HID-${randomCode}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      healthId,
      isPremium: false,
      subscriptionPlan: 'standard'
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], interactions: []
    };

    try {
      await new Promise(r => setTimeout(r, 2000));
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Vault initialization failed.");
    } finally {
      setIsScanning(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsScanning(true);
    const inputId = (loginId || '').trim().toUpperCase();

    try {
      await new Promise(r => setTimeout(r, 1500));
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Identity key not recognized. Access denied.");
      }
    } catch (err) {
      setAuthError("Vault synchronization error.");
    } finally {
      setIsScanning(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  const initiatePaymentVerification = async () => {
    if (selectedMethod === 'upi') {
      const amount = PLANS[selectedPlan].price;
      const upiLink = `upi://pay?pa=shakeelmohamed082@oksbi&pn=Shakeel Mohamed&am=${amount}&cu=INR`;
      window.location.href = upiLink;
      setPaymentStep('verifying');
    } else {
      setPaymentStep('verifying');
    }

    const steps = ["Initializing Secure Protocol...", "Authenticating Identity...", "Finalizing Vault Encryption..."];
    for (const step of steps) {
      setVerificationSubStep(step);
      await new Promise(r => setTimeout(r, 1000));
    }

    if (!currentUser) return;
    const expiry = new Date();
    expiry.setFullYear(expiry.getFullYear() + 1);
    const updatedUser: HealthRecord = {
      ...currentUser,
      profile: { ...currentUser.profile, isPremium: true, subscriptionPlan: selectedPlan, subscriptionExpiry: expiry.toISOString() }
    };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
    setPaymentStep('success');
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = { ...currentUser, [type]: [...collection, { ...item, id: Date.now().toString() }] };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
    setShowAddModal(null);
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = { ...currentUser, [type]: collection.filter((item: any) => item.id !== itemId) };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
  };

  const updateMedicalItemStatus = async (type: keyof HealthRecord, itemId: string, newStatus: string) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = {
      ...currentUser,
      [type]: collection.map((item: any) => item.id === itemId ? { ...item, status: newStatus } : item)
    };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    const currentQ = userQuery;
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, currentQ);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const filteredSearchResults = useMemo(() => {
    if (!currentUser || !globalSearchTerm.trim()) return null;
    const term = globalSearchTerm.toLowerCase();
    return {
      problems: (currentUser.problems || []).filter(p => p.condition.toLowerCase().includes(term)),
      medications: (currentUser.medications || []).filter(m => m.name.toLowerCase().includes(term))
    };
  }, [currentUser, globalSearchTerm]);

  const foundPatients = useMemo(() => {
    if (!patientLookupTerm.trim()) return [];
    return allPatients.filter(p => p.profile.healthId.includes(patientLookupTerm.toUpperCase()));
  }, [allPatients, patientLookupTerm]);

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-indigo-300 font-bold uppercase tracking-widest text-xs">Initializing Vault...</p>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 lg:p-12 relative overflow-hidden">
        <div className="absolute inset-0 opacity-20">
          <div className="absolute top-[20%] left-[10%] w-96 h-96 bg-indigo-600 rounded-full blur-[150px] animate-pulse"></div>
          <div className="absolute bottom-[20%] right-[10%] w-96 h-96 bg-emerald-600 rounded-full blur-[150px] animate-pulse" style={{ animationDelay: '2s' }}></div>
        </div>

        <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-12 bg-white/5 backdrop-blur-2xl rounded-[3.5rem] overflow-hidden border border-white/10 shadow-2xl relative z-10">
          <div className="lg:col-span-5 bg-indigo-950 p-12 text-white flex flex-col justify-between relative border-r border-white/5">
            <div className="relative z-10">
              <div className="flex items-center gap-4 mb-16">
                <div className="w-14 h-14 bg-indigo-500 rounded-2xl flex items-center justify-center text-white text-2xl">{ICONS.LOCK}</div>
                <h1 className="text-2xl font-black uppercase tracking-tighter italic">{APP_NAME}</h1>
              </div>
              <h2 className="text-6xl font-black leading-tight tracking-tighter">Your <span className="text-indigo-400">Vault</span>,<br/>Your <span className="text-indigo-400">Rules</span>.</h2>
              <p className="text-lg text-indigo-200/70 mt-8 font-medium max-w-sm">Clinical history stored strictly on your local device. Decrypt with your unique ID.</p>
            </div>
          </div>

          <div className="lg:col-span-7 bg-slate-50 p-12 lg:p-20 flex flex-col justify-center relative">
            {isScanning && (
              <div className="absolute inset-0 z-50 bg-slate-50/80 backdrop-blur-md flex flex-col items-center justify-center">
                <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="font-black text-slate-800 uppercase tracking-widest text-xs">Authenticating Vault...</p>
              </div>
            )}

            {showRegSuccess ? (
              <div className="max-w-md mx-auto w-full text-center animate-pop-in">
                <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-[2rem] flex items-center justify-center text-5xl mx-auto mb-8 shadow-xl"><i className="fas fa-id-badge"></i></div>
                <h3 className="text-4xl font-black text-slate-800 tracking-tight mb-4">Vault Created</h3>
                <div className="bg-white p-10 rounded-[3rem] border-2 border-dashed border-indigo-200 mb-10">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Identity Health ID</p>
                  <p className="text-5xl font-mono font-black text-indigo-600 tracking-widest">{showRegSuccess}</p>
                </div>
                <button onClick={completeRegistration} className="w-full py-6 bg-slate-900 text-white font-black rounded-[2rem] shadow-2xl hover:bg-indigo-600 transition-all uppercase tracking-widest text-lg">Unlock My Vault</button>
              </div>
            ) : (
              <div className="max-w-md mx-auto w-full">
                <div className="relative bg-slate-200 p-1.5 rounded-[2.2rem] flex mb-16 shadow-inner">
                   <button onClick={() => setAuthMode('login')} className={`relative z-10 flex-1 py-4 text-[11px] font-black uppercase tracking-widest rounded-[1.8rem] transition-all ${authMode === 'login' ? 'bg-white text-indigo-600 shadow-xl' : 'text-slate-500'}`}>Existing User</button>
                   <button onClick={() => setAuthMode('register')} className={`relative z-10 flex-1 py-4 text-[11px] font-black uppercase tracking-widest rounded-[1.8rem] transition-all ${authMode === 'register' ? 'bg-white text-indigo-600 shadow-xl' : 'text-slate-500'}`}>New Patient</button>
                </div>

                {authMode === 'login' ? (
                  <form onSubmit={handleLogin} className="space-y-10 animate-slide-in">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Identity Access Key</label>
                      <input required value={loginId} onChange={(e) => setLoginId(e.target.value.toUpperCase())} placeholder="HID-XXXXXX" className="w-full px-8 py-6 rounded-[2.2rem] bg-white border border-slate-200 text-2xl font-mono uppercase focus:border-indigo-500 outline-none transition-all shadow-sm" />
                    </div>
                    <button type="submit" className="w-full bg-indigo-600 text-white font-black py-6 rounded-[2.2rem] text-lg hover:bg-indigo-700 shadow-xl transition-all">Secure Login <i className="fas fa-unlock ml-2"></i></button>
                  </form>
                ) : (
                  <form onSubmit={handleRegister} className="space-y-6 animate-slide-in max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
                    <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-4">
                      <input required name="name" placeholder="Full Legal Name" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-medium" />
                      <div className="grid grid-cols-2 gap-4">
                        <input required name="age" type="number" placeholder="Age" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                        <select required name="bloodGroup" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-bold uppercase">
                          <option value="">Blood Group</option>
                          {['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                        </select>
                      </div>
                      <input required name="phone" placeholder="Contact Phone" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                      <input required name="aadhaar" pattern="[0-9]{12}" placeholder="Aadhaar (12 Digits)" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                      <input required name="dob" type="date" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                    </div>
                    <button type="submit" className="w-full bg-emerald-600 text-white font-black py-6 rounded-[2.5rem] shadow-xl hover:bg-emerald-700 transition-all uppercase tracking-widest">Initialize Vault</button>
                  </form>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout} isPremium={currentUser?.profile?.isPremium}>
      {activeTab === 'dashboard' ? (
        <div className="space-y-6 animate-pop-in">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className={`lg:col-span-2 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden ${currentUser?.profile?.isPremium ? 'bg-slate-900' : 'bg-indigo-600'}`}>
              <div className="relative z-10">
                <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-8">Clinical Identity Passport</p>
                <h1 className="text-5xl font-mono font-black mb-12 tracking-wider">{currentUser?.profile?.healthId}</h1>
                <div className="grid grid-cols-3 gap-8">
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Blood Group</p><p className="font-black text-2xl">{currentUser?.profile?.bloodGroup}</p></div>
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Age</p><p className="font-black text-2xl">{currentUser?.profile?.age}</p></div>
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Vault Status</p><p className="font-black text-sm uppercase tracking-widest text-emerald-400">Encrypted</p></div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-[2.5rem] p-10 shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-3xl mb-4">{ICONS.SHIELD_CHECK}</div>
              <p className="font-black text-emerald-600 italic">AES-256 Active</p>
              <p className="text-[10px] text-slate-400 mt-2">Data is isolated on your device.</p>
            </div>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {[
              { label: 'Conditions', val: (currentUser?.problems || []).length, icon: ICONS.MEDICAL },
              { label: 'Medications', val: (currentUser?.medications || []).length, icon: ICONS.MEDS },
              { label: 'Surgeries', val: (currentUser?.surgeries || []).length, icon: ICONS.SURGERY },
              { label: 'Allergies', val: (currentUser?.allergies || []).length, icon: ICONS.ALLERGY },
            ].map((s, i) => (
              <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-6 group hover:border-indigo-100 hover:shadow-lg transition-all">
                <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-2xl group-hover:bg-indigo-600 group-hover:text-white transition-all">{s.icon}</div>
                <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{s.label}</p><p className="text-2xl font-black text-slate-800">{s.val}</p></div>
              </div>
            ))}
          </div>
          {/* Government Aid Highlight Section */}
          <div className="bg-amber-50 rounded-[2.5rem] p-10 border border-amber-200 relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-10 text-amber-100 text-9xl -rotate-12 transition-transform group-hover:rotate-0">
              <i className="fas fa-landmark"></i>
            </div>
            <div className="relative z-10">
              <h3 className="text-xl font-black text-amber-900 mb-4 flex items-center gap-3">
                <i className="fas fa-landmark-dome"></i> Government Scheme Navigator
              </h3>
              <p className="text-sm text-amber-800/80 font-medium max-w-2xl leading-relaxed">
                August AI can identify eligibility for healthcare aid based on your profile. Currently monitoring schemes like PM-JAY and RSBY.
              </p>
              <button 
                onClick={() => { setActiveTab('august'); setUserQuery("What government health schemes am I eligible for based on my medical history?"); askAugustAI(); }}
                className="mt-8 px-8 py-4 bg-amber-600 text-white font-black rounded-2xl shadow-xl shadow-amber-900/10 hover:bg-amber-700 transition-all uppercase tracking-widest text-xs"
              >
                Check Eligibility Now
              </button>
            </div>
          </div>
        </div>
      ) : activeTab === 'records' ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 pb-32 animate-pop-in">
          {/* Medical Problems Card */}
          <RecordCard title="Clinical Conditions" icon={ICONS.MEDICAL} onAdd={() => setShowAddModal('problem')}>
            <div className="space-y-6">
              {(currentUser?.problems || []).length === 0 && (
                <div className="text-center py-10 text-slate-400 italic text-sm">No conditions recorded in this vault.</div>
              )}
              {(currentUser?.problems || []).map(p => (
                <div key={p.id} className={`p-6 rounded-[2rem] border-2 transition-all hover:scale-[1.02] flex flex-col gap-4 group relative ${
                  p.severity === 'severe' ? 'bg-rose-50/60 border-rose-100' : 
                  p.severity === 'moderate' ? 'bg-amber-50/60 border-amber-100' : 'bg-emerald-50/60 border-emerald-100'
                }`}>
                  <div className="flex justify-between items-start">
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl bg-white shadow-sm border ${
                        p.severity === 'severe' ? 'text-rose-600 border-rose-200' : 
                        p.severity === 'moderate' ? 'text-amber-600 border-amber-200' : 'text-emerald-600 border-emerald-200'
                      }`}>
                        <i className={`fas ${p.status === 'present' ? 'fa-virus-covid' : 'fa-circle-check'}`}></i>
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-lg tracking-tight">{p.condition}</h4>
                        <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-1 rounded bg-white border ${
                          p.status === 'present' ? 'text-rose-500 border-rose-200' : 'text-emerald-500 border-emerald-200'
                        }`}>{p.status}</span>
                      </div>
                    </div>
                    <button onClick={() => removeMedicalItem('problems', p.id)} className="text-slate-300 hover:text-rose-600 transition-colors opacity-0 group-hover:opacity-100 p-2"><i className="fas fa-trash-alt"></i></button>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white/80 p-4 rounded-2xl border border-white/50 flex flex-col gap-1">
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Severity Level</span>
                      <p className={`text-sm font-black uppercase tracking-wide ${
                        p.severity === 'severe' ? 'text-rose-600' : 
                        p.severity === 'moderate' ? 'text-amber-600' : 'text-emerald-600'
                      }`}>{p.severity}</p>
                    </div>
                    <div className="bg-white/80 p-4 rounded-2xl border border-white/50 flex flex-col gap-1">
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Onset Date</span>
                      <p className="text-sm font-black text-slate-700">{p.onsetDate}</p>
                    </div>
                  </div>

                  {/* Enhanced Scheme Integration for Problems */}
                  <div className="bg-white/90 p-5 rounded-[2rem] border border-amber-200 shadow-sm mt-2 relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-3 opacity-10">
                      <i className="fas fa-landmark text-4xl text-amber-600"></i>
                    </div>
                    <p className="text-[10px] font-black text-amber-700 uppercase tracking-[0.2em] mb-3 flex items-center gap-2">
                      <i className="fas fa-landmark-dome"></i> Financial Aid & Schemes
                    </p>
                    <div className="space-y-3">
                      {p.applicableSchemes && p.applicableSchemes.length > 0 ? p.applicableSchemes.map(s => (
                        <div key={s.id} className="p-3 bg-amber-50 rounded-xl border border-amber-100">
                          <h5 className="text-[11px] font-black text-amber-900">{s.name}</h5>
                          <p className="text-[10px] text-amber-800 mt-1 leading-relaxed opacity-80">{s.benefits}</p>
                        </div>
                      )) : (
                        <div className="text-center py-2">
                           <button 
                             onClick={() => { setActiveTab('august'); setUserQuery(`Search for Indian Government Health Schemes applicable for ${p.condition} for a ${currentUser?.profile.age} year old.`); askAugustAI(); }}
                             className="text-[9px] font-black text-amber-600 hover:text-amber-800 uppercase tracking-widest"
                           >
                             <i className="fas fa-search-plus mr-1"></i> Scan for applicable aid
                           </button>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </RecordCard>

          {/* Active Medications Card */}
          <RecordCard title="Pharmacy Vault" icon={ICONS.MEDS} onAdd={() => setShowAddModal('medication')}>
             <div className="space-y-6">
              {(currentUser?.medications || []).length === 0 && (
                <div className="text-center py-10 text-slate-400 italic text-sm">No active prescriptions logged.</div>
              )}
              {(currentUser?.medications || []).map(m => (
                <div key={m.id} className="p-6 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col gap-5 relative group hover:border-indigo-100 transition-all">
                  <div className="flex justify-between items-start">
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-2xl shadow-inner border border-indigo-100/50">
                        <i className="fas fa-capsules"></i>
                      </div>
                      <div>
                        <h4 className="font-black text-slate-800 text-lg tracking-tight">{m.name}</h4>
                        <div className="flex items-center gap-2 mt-1">
                          <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Active Intake</span>
                        </div>
                      </div>
                    </div>
                    <button onClick={() => removeMedicalItem('medications', m.id)} className="text-slate-300 hover:text-rose-600 transition-colors opacity-0 group-hover:opacity-100 p-2"><i className="fas fa-trash-alt"></i></button>
                  </div>

                  <div className="bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100 flex flex-col md:flex-row gap-6">
                    <div className="flex-1">
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Dosage Schedule</span>
                      <p className="text-sm font-black text-slate-700">{m.dosage} • {m.frequency}</p>
                    </div>
                    <div className="flex-1 md:border-l border-slate-200 md:pl-6">
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Prescription Date</span>
                      <p className="text-sm font-black text-slate-700">{m.startDate}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </RecordCard>

          {/* Surgical History Card */}
          <RecordCard title="Surgical Records" icon={ICONS.SURGERY} onAdd={() => setShowAddModal('surgery')}>
            <div className="space-y-6">
               {(currentUser?.surgeries || []).length === 0 && (
                <div className="text-center py-10 text-slate-400 italic text-sm">No surgical records found.</div>
              )}
              {(currentUser?.surgeries || []).map(s => (
                <div key={s.id} className="p-6 bg-slate-50/50 rounded-[2.2rem] border border-slate-100 flex flex-col gap-4 hover:bg-white hover:shadow-lg transition-all group">
                   <div className="flex justify-between items-start">
                     <div className="flex items-center gap-4">
                       <div className="w-10 h-10 rounded-xl bg-white text-indigo-600 flex items-center justify-center text-lg border border-slate-100">
                         <i className="fas fa-hospital-user"></i>
                       </div>
                       <div>
                         <h4 className="font-black text-slate-800">{s.type}</h4>
                         <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">{s.hospital}</p>
                       </div>
                     </div>
                     <button onClick={() => removeMedicalItem('surgeries', s.id)} className="text-slate-300 hover:text-rose-600 transition-colors opacity-0 group-hover:opacity-100 p-2"><i className="fas fa-trash-alt"></i></button>
                   </div>
                   <div className="flex items-center gap-6 px-2 text-xs font-bold text-slate-500">
                      <div className="flex items-center gap-2"><i className="far fa-calendar-alt opacity-50"></i> {s.date}</div>
                      {s.surgeon && <div className="flex items-center gap-2"><i className="fas fa-user-md opacity-50"></i> Dr. {s.surgeon}</div>}
                   </div>
                </div>
              ))}
            </div>
          </RecordCard>

          {/* Allergies Profile Card */}
          <RecordCard title="Allergy Sensitivity" icon={ICONS.ALLERGY} onAdd={() => setShowAddModal('allergy')}>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
               {(currentUser?.allergies || []).length === 0 && (
                <div className="col-span-2 text-center py-10 text-slate-400 italic text-sm">No known allergies registered.</div>
              )}
              {(currentUser?.allergies || []).map(a => (
                <div key={a.id} className="p-6 bg-white rounded-[2rem] border border-slate-100 shadow-sm hover:border-indigo-200 transition-all group relative">
                  <div className="flex items-start justify-between mb-4">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${
                      a.severity === 'high' ? 'bg-rose-50 text-rose-500' : 
                      a.severity === 'moderate' ? 'bg-amber-50 text-amber-500' : 'bg-emerald-50 text-emerald-500'
                    }`}>
                      <i className="fas fa-shield-virus"></i>
                    </div>
                    <button onClick={() => removeMedicalItem('allergies', a.id)} className="text-slate-300 hover:text-rose-600 transition-colors opacity-0 group-hover:opacity-100"><i className="fas fa-trash-alt"></i></button>
                  </div>
                  <h4 className="font-black text-slate-800 uppercase tracking-tight">{a.substance}</h4>
                  <div className="mt-3 flex items-center gap-2">
                    <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-1 rounded-full ${
                      a.severity === 'high' ? 'bg-rose-500 text-white' : 
                      a.severity === 'moderate' ? 'bg-amber-500 text-white' : 'bg-emerald-500 text-white'
                    }`}>{a.severity} risk</span>
                  </div>
                  {a.reaction && <p className="mt-3 text-[10px] text-slate-500 font-medium leading-relaxed italic">{a.reaction}</p>}
                </div>
              ))}
            </div>
          </RecordCard>
        </div>
      ) : activeTab === 'august' ? (
        <div className="h-[calc(100vh-14rem)] flex flex-col bg-white rounded-[3rem] p-8 shadow-sm border border-slate-100 overflow-hidden animate-pop-in">
           <div className="flex items-center gap-4 pb-6 border-b border-slate-50">
                <div className="w-14 h-14 rounded-2xl bg-slate-900 text-white flex items-center justify-center text-2xl shadow-xl">{ICONS.AI}</div>
                <div>
                    <h3 className="font-black text-xl tracking-tight">August AI Analyst</h3>
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Live Clinical Analysis Enabled</p>
                </div>
           </div>
           <div className="flex-grow overflow-y-auto space-y-6 my-6 pr-4 custom-scrollbar">
             {chatHistory.length === 0 && (
               <div className="h-full flex flex-col items-center justify-center text-center opacity-30">
                 <i className="fas fa-dna text-7xl mb-8 animate-pulse text-indigo-300"></i>
                 <p className="font-black text-2xl text-indigo-900 tracking-tight">Vault Data Processor</p>
                 <p className="text-sm max-w-xs mx-auto mt-2 leading-relaxed">Ask about drug interactions, chronic condition support, or government schemes.</p>
               </div>
             )}
             {chatHistory.map((m, i) => (
               <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-in`}>
                 <div className={`max-w-[85%] p-6 rounded-[2rem] text-sm leading-relaxed shadow-sm ${m.role === 'user' ? 'bg-indigo-600 text-white shadow-indigo-200' : 'bg-slate-100 text-slate-800 border border-slate-200/50'}`}>
                   {m.content}
                 </div>
               </div>
             ))}
             {isAiLoading && <div className="text-[10px] font-black text-indigo-400 uppercase tracking-widest flex items-center gap-3 ml-2"><i className="fas fa-dna fa-spin text-lg"></i> Analyzing Secure Records...</div>}
           </div>
           <div className="flex gap-3 bg-slate-50 p-3 rounded-[2rem] border border-slate-200">
             <input value={userQuery} onChange={(e) => setUserQuery(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && askAugustAI()} placeholder="Ask August about your health..." className="flex-grow px-6 py-4 bg-transparent outline-none font-medium" />
             <button onClick={askAugustAI} disabled={!userQuery.trim() || isAiLoading} className="w-14 h-14 bg-indigo-600 text-white rounded-2xl shadow-lg flex items-center justify-center transition-all disabled:opacity-30"><i className="fas fa-paper-plane"></i></button>
           </div>
        </div>
      ) : activeTab === 'subscription' ? (
        <div className="pb-32 animate-pop-in">
          <div className="max-w-4xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-8">
            {Object.entries(PLANS).map(([key, plan]) => (
              <div key={key} className={`p-10 rounded-[3rem] border-2 transition-all relative overflow-hidden flex flex-col cursor-pointer ${selectedPlan === key ? 'border-indigo-600 bg-white shadow-2xl scale-[1.02]' : 'border-slate-100 bg-slate-50 opacity-80'}`} onClick={() => setSelectedPlan(key as PlanType)}>
                <h3 className="text-2xl font-black mb-2">{plan.name}</h3>
                <div className="text-4xl font-black mb-8">₹{plan.price}<span className="text-xs font-bold text-slate-400 uppercase tracking-widest">/mo</span></div>
                <ul className="space-y-4 mb-12 flex-grow">
                  {plan.features.map(f => <li key={f} className="text-sm font-medium text-slate-600 flex items-center gap-2"><i className="fas fa-check text-emerald-500"></i> {f}</li>)}
                </ul>
                <button onClick={() => { setShowPaymentModal(true); setPaymentStep('summary'); }} className="w-full py-5 rounded-3xl font-black uppercase tracking-widest text-xs bg-indigo-600 text-white">Unlock {plan.name}</button>
              </div>
            ))}
          </div>
        </div>
      ) : activeTab === 'history' ? (
        <div className="space-y-8 pb-32 animate-pop-in">
          <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
            <h3 className="text-xl font-black mb-6 flex items-center gap-3">Vault Search</h3>
            <input value={globalSearchTerm} onChange={(e) => setGlobalSearchTerm(e.target.value)} className="w-full p-6 rounded-3xl bg-slate-50 border border-slate-100 outline-none" placeholder="Search across all clinical records..." />
            {filteredSearchResults && (
              <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
                {filteredSearchResults.problems.map(p => <div key={p.id} className="p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100/50 font-bold">{p.condition}</div>)}
              </div>
            )}
          </div>
        </div>
      ) : null}

      {/* Payment Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl animate-pop-in">
          <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-10 shadow-2xl relative overflow-hidden">
             <div className="flex items-center justify-between mb-10">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-xl shadow-inner"><i className="fas fa-shield-alt"></i></div>
                  <h3 className="text-xl font-black tracking-tight">{paymentStep === 'success' ? 'Vault Upgraded' : 'Secure Checkout'}</h3>
                </div>
                {paymentStep !== 'verifying' && <button onClick={() => setShowPaymentModal(false)} className="w-10 h-10 rounded-full bg-slate-100 text-slate-400 hover:text-rose-500 transition-all"><i className="fas fa-times"></i></button>}
             </div>

             {paymentStep === 'summary' && (
               <div className="space-y-8 animate-slide-in">
                 <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 space-y-4">
                    <div className="flex justify-between items-center"><span className="text-xs font-bold text-slate-500 uppercase">Selected Plan</span><span className="font-black text-slate-800">{PLANS[selectedPlan].name}</span></div>
                    <div className="pt-4 border-t border-slate-200 flex justify-between items-center"><span className="text-sm font-black uppercase">Total to Pay</span><span className="text-3xl font-black text-indigo-600">₹{PLANS[selectedPlan].price}</span></div>
                 </div>
                 <button onClick={() => setPaymentStep('method')} className="w-full py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-xl uppercase tracking-widest text-sm">Select Method</button>
               </div>
             )}

             {paymentStep === 'method' && (
               <div className="space-y-6 animate-slide-in">
                 <button onClick={() => { setSelectedMethod('upi'); initiatePaymentVerification(); }} className="w-full p-6 rounded-[2rem] border-2 border-slate-100 hover:border-indigo-600 flex items-center gap-5 transition-all">
                    <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center text-xl">{ICONS.UPI}</div>
                    <div className="text-left"><p className="font-black text-slate-800">UPI Smart Pay</p><p className="text-[10px] font-bold text-slate-400">GPay, PhonePe, Paytm</p></div>
                 </button>
                 <button onClick={() => setPaymentStep('summary')} className="w-full py-5 text-slate-400 font-bold uppercase text-[10px]">Back to Summary</button>
               </div>
             )}

             {paymentStep === 'verifying' && (
               <div className="py-20 text-center space-y-8 animate-pop-in">
                 <div className="w-20 h-20 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                 <p className="text-2xl font-black text-slate-800">{verificationSubStep}</p>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Secure session active</p>
               </div>
             )}

             {paymentStep === 'success' && (
               <div className="py-10 text-center space-y-8 animate-pop-in">
                 <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2.5rem] flex items-center justify-center text-5xl mx-auto shadow-2xl border border-emerald-100">{ICONS.SHIELD_CHECK}</div>
                 <h3 className="text-3xl font-black mb-2 tracking-tight">Payment Verified</h3>
                 <p className="text-slate-500 font-medium px-8 text-sm leading-relaxed">Vault successfully upgraded to <span className="text-indigo-600 font-bold">{PLANS[selectedPlan].name}</span>.</p>
                 <button onClick={() => { setShowPaymentModal(false); setActiveTab('dashboard'); }} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl uppercase tracking-widest text-xs">Access Premium Vault</button>
               </div>
             )}
          </div>
        </div>
      )}

      {/* Add Record Modals */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xl">
          <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-10 shadow-2xl animate-pop-in max-h-[90vh] overflow-y-auto border border-slate-200">
            <div className="flex items-center gap-4 mb-10">
                <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">
                    {showAddModal === 'problem' ? ICONS.MEDICAL : 
                     showAddModal === 'medication' ? ICONS.MEDS : 
                     showAddModal === 'allergy' ? ICONS.ALLERGY : ICONS.SURGERY}
                </div>
                <div><h3 className="text-2xl font-black tracking-tight capitalize">New {showAddModal}</h3></div>
            </div>
            <form onSubmit={(e) => {
              e.preventDefault();
              const f = new FormData(e.currentTarget);
              if (showAddModal === 'problem') addMedicalItem('problems', { condition: f.get('condition'), severity: f.get('severity'), onsetDate: f.get('date'), status: 'present' });
              if (showAddModal === 'medication') addMedicalItem('medications', { name: f.get('name'), dosage: f.get('dosage'), frequency: f.get('freq'), startDate: f.get('date'), status: 'active' });
              if (showAddModal === 'allergy') addMedicalItem('allergies', { substance: f.get('substance'), severity: f.get('severity'), reaction: f.get('reaction'), status: 'active' });
              if (showAddModal === 'surgery') addMedicalItem('surgeries', { type: f.get('type'), date: f.get('date'), hospital: f.get('hospital'), surgeon: f.get('surgeon') });
            }} className="space-y-6">
              {showAddModal === 'problem' && (
                <>
                  <input required name="condition" placeholder="Condition (e.g. Type 2 Diabetes)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:border-indigo-500 font-bold" />
                  <div className="grid grid-cols-2 gap-4">
                    <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px] tracking-widest">
                      <option value="mild">Mild</option><option value="moderate">Moderate</option><option value="severe">Severe</option>
                    </select>
                    <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" />
                  </div>
                </>
              )}
              {showAddModal === 'medication' && (
                <>
                  <input required name="name" placeholder="Medication Name" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" />
                  <div className="grid grid-cols-2 gap-4">
                    <input required name="dosage" placeholder="Dosage (e.g. 500mg)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                    <input required name="freq" placeholder="Freq (e.g. Daily)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  </div>
                  <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                </>
              )}
              {showAddModal === 'allergy' && (
                <>
                  <input required name="substance" placeholder="Allergen (e.g. Peanuts)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" />
                  <div className="grid grid-cols-2 gap-4">
                    <select name="severity" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold uppercase text-[10px] tracking-widest">
                      <option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option>
                    </select>
                    <input name="reaction" placeholder="Reaction (e.g. Skin Rash)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  </div>
                </>
              )}
              {showAddModal === 'surgery' && (
                <>
                  <input required name="type" placeholder="Procedure (e.g. Appendectomy)" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" />
                  <div className="grid grid-cols-2 gap-4">
                    <input required type="date" name="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                    <input name="surgeon" placeholder="Lead Surgeon" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                  </div>
                  <input required name="hospital" placeholder="Hospital Facility" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-2xl outline-none" />
                </>
              )}
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 bg-slate-100 rounded-3xl font-black uppercase text-[10px] text-slate-500">Discard</button>
                <button type="submit" className="flex-[2] py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl uppercase text-[10px]">Commit to Vault</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React from 'react';
import { ICONS, APP_NAME } from '../constants';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onLogout: () => void;
  userName: string;
  isPremium?: boolean;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, onLogout, userName, isPremium }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: ICONS.DASHBOARD },
    { id: 'records', label: 'Medical Records', icon: ICONS.MEDICAL },
    { id: 'august', label: 'August AI', icon: ICONS.AI },
    { id: 'history', label: 'Search History', icon: ICONS.SEARCH },
  ];

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {/* Sidebar for Desktop */}
      <aside className="w-full md:w-64 bg-indigo-950 text-white flex-shrink-0 md:min-h-screen shadow-2xl z-40">
        <div className="p-6 flex items-center space-x-3">
          <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center text-indigo-950 text-xl shadow-lg transform transition-transform hover:rotate-12">
            {ICONS.LOCK}
          </div>
          <h1 className="text-xl font-bold tracking-tight">{APP_NAME}</h1>
        </div>

        <div className="px-4 py-2 mb-6">
          <div className="bg-indigo-900/50 border border-white/5 rounded-2xl p-4 flex items-center space-x-3 relative overflow-hidden group transition-all hover:bg-indigo-900/80">
            {isPremium && (
              <div className="absolute top-0 right-0 p-1">
                <i className="fas fa-crown text-amber-400 text-[10px] animate-bounce"></i>
              </div>
            )}
            <div className={`w-10 h-10 rounded-full flex items-center justify-center text-xl transition-transform group-hover:scale-110 ${isPremium ? 'bg-amber-500 text-white' : 'bg-indigo-400'}`}>
              {isPremium ? <i className="fas fa-crown"></i> : ICONS.USER}
            </div>
            <div className="overflow-hidden">
              <p className="text-[10px] uppercase font-bold text-indigo-300 tracking-wider">
                {isPremium ? 'Premium Patient' : 'Standard Access'}
              </p>
              <p className="font-semibold truncate">{userName}</p>
            </div>
          </div>
        </div>

        <nav className="flex-grow px-2 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-300 group relative ${
                activeTab === item.id
                  ? 'bg-white text-indigo-950 shadow-lg translate-x-1'
                  : 'text-indigo-100 hover:bg-indigo-900/50 hover:translate-x-1'
              }`}
            >
              <span className={`text-lg transition-transform group-hover:scale-110 ${activeTab === item.id ? 'text-indigo-600' : ''}`}>{item.icon}</span>
              <span className="font-medium">{item.label}</span>
              {activeTab === item.id && (
                <div className="absolute left-0 w-1 h-6 bg-indigo-500 rounded-full" />
              )}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto">
          <button 
            onClick={onLogout}
            className="w-full flex items-center justify-center space-x-2 px-4 py-3 bg-red-500/10 hover:bg-red-500 text-red-100 rounded-xl transition-all duration-300 hover:shadow-lg hover:shadow-red-500/20 group"
          >
            <span className="transition-transform group-hover:-translate-x-1">{ICONS.LOGOUT}</span>
            <span className="font-medium">Logout</span>
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-grow flex flex-col min-w-0">
        <header className="h-16 bg-white/80 backdrop-blur-md border-b border-slate-200 flex items-center justify-between px-6 sticky top-0 z-20">
          <h2 className="text-lg font-semibold text-slate-800 capitalize">
            {navItems.find(n => n.id === activeTab)?.label}
          </h2>
          <div className="flex items-center space-x-4">
            <div className="flex items-center text-xs font-medium text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 shadow-sm">
              <span className="w-2 h-2 bg-emerald-500 rounded-full mr-2 animate-pulse"></span>
              Vault Encryption Active
            </div>
          </div>
        </header>

        <div className="p-6 flex-grow overflow-y-auto">
          {children}
        </div>
      </main>

      {/* Mobile Bottom Nav */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-lg border-t border-slate-200 flex items-center justify-around py-3 px-1 z-30 shadow-[0_-10px_30px_-15px_rgba(0,0,0,0.1)] overflow-x-auto">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`flex flex-col items-center px-4 py-1 rounded-xl transition-all duration-300 flex-shrink-0 min-w-[64px] ${
              activeTab === item.id ? 'text-indigo-600 scale-110' : 'text-slate-400 opacity-60'
            }`}
          >
            <span className="text-xl">{item.icon}</span>
            <span className="text-[8px] mt-1 font-bold uppercase tracking-tighter">{item.label.split(' ')[0]}</span>
          </button>
        ))}
      </div>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, HealthRecord, ChatMessage, Interaction, MedicalProblem, Medication, Surgery, Allergy, TreatmentNote, GovernmentScheme } from './types';
import { ICONS, APP_NAME } from './constants';
import Layout from './components/Layout';
import RecordCard from './components/RecordCard';
import { analyzeHealthRecord } from './services/geminiService';
import { dbService } from './services/dbService';

const SESSION_KEY = 'health_shield_active_session';
const LAST_HID_KEY = 'health_shield_last_hid';

type ModalType = 'problem' | 'note' | 'medication' | 'surgery' | 'allergy' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<HealthRecord | null>(null);
  const [allPatients, setAllPatients] = useState<HealthRecord[]>([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAuth, setIsAuth] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [showRegSuccess, setShowRegSuccess] = useState<string | null>(null);

  const [loginId, setLoginId] = useState('');
  const [authError, setAuthError] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isScanning, setIsScanning] = useState(false);

  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [userQuery, setUserQuery] = useState('');
  const [globalSearchTerm, setGlobalSearchTerm] = useState('');
  const [patientLookupTerm, setPatientLookupTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState<ModalType>(null);

  const lastHid = localStorage.getItem(LAST_HID_KEY);

  useEffect(() => {
    const bootstrap = async () => {
      try {
        await dbService.init();
        const activeSession = localStorage.getItem(SESSION_KEY);
        if (activeSession) {
          const found = await dbService.getRecord(activeSession);
          if (found) {
            setCurrentUser(found);
            setIsAuth(true);
          }
        }
        const records = await dbService.getAllRecords();
        setAllPatients(records);
      } catch (e) {
        console.error("Database initialization failed", e);
      } finally {
        setTimeout(() => setIsLoading(false), 1200);
      }
    };
    bootstrap();
  }, [isAuth]);

  const handleRegister = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setAuthError('');
    setIsScanning(true);

    const formData = new FormData(e.currentTarget);
    const randomCode = Math.random().toString(36).substring(2, 8).toUpperCase();
    const healthId = `HID-${randomCode}`;

    const newProfile: UserProfile = {
      name: (formData.get('name') as string) || '',
      age: parseInt(formData.get('age') as string) || 0,
      dob: (formData.get('dob') as string) || '',
      gender: (formData.get('gender') as string) || 'Other',
      phone: (formData.get('phone') as string) || '',
      aadhaar: (formData.get('aadhaar') as string) || '',
      bloodGroup: (formData.get('bloodGroup') as string) || '',
      healthId,
      isPremium: false,
      subscriptionPlan: 'standard'
    };

    const newRecord: HealthRecord = {
      profile: newProfile,
      problems: [], medications: [], surgeries: [], allergies: [], notes: [], interactions: []
    };

    try {
      await new Promise(r => setTimeout(r, 2000));
      await dbService.saveRecord(newRecord);
      localStorage.setItem(LAST_HID_KEY, healthId);
      setShowRegSuccess(healthId);
    } catch (err) {
      setAuthError("Vault initialization failed.");
    } finally {
      setIsScanning(false);
    }
  };

  const completeRegistration = async () => {
    if (!showRegSuccess) return;
    const found = await dbService.getRecord(showRegSuccess);
    if (found) {
      setCurrentUser(found);
      localStorage.setItem(SESSION_KEY, showRegSuccess);
      setIsAuth(true);
      setShowRegSuccess(null);
    }
  };

  const handleLogin = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setAuthError('');
    setIsScanning(true);
    const inputId = (loginId || '').trim().toUpperCase();

    try {
      await new Promise(r => setTimeout(r, 1500));
      const found = await dbService.getRecord(inputId);
      if (found) {
        setCurrentUser(found);
        localStorage.setItem(SESSION_KEY, found.profile.healthId);
        setIsAuth(true);
      } else {
        setAuthError("Identity key not recognized. Access denied.");
      }
    } catch (err) {
      setAuthError("Vault synchronization error.");
    } finally {
      setIsScanning(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem(SESSION_KEY);
    setIsAuth(false);
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  const addMedicalItem = async (type: keyof HealthRecord, item: any) => {
    if (!currentUser) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = { ...currentUser, [type]: [...collection, { ...item, id: Date.now().toString() }] };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
    setShowAddModal(null);
  };

  const removeMedicalItem = async (type: keyof HealthRecord, itemId: string) => {
    if (!currentUser || !confirm("Delete this record permanently?")) return;
    const collection = (currentUser[type] as any[]) || [];
    const updatedUser = { ...currentUser, [type]: collection.filter((item: any) => item.id !== itemId) };
    await dbService.saveRecord(updatedUser);
    setCurrentUser(updatedUser);
  };

  const askAugustAI = async () => {
    if (!userQuery.trim() || !currentUser) return;
    const userMsg: ChatMessage = { role: 'user', content: userQuery, timestamp: Date.now() };
    setChatHistory(prev => [...prev, userMsg]);
    const currentQ = userQuery;
    setUserQuery('');
    setIsAiLoading(true);

    try {
      const response = await analyzeHealthRecord(currentUser, currentQ);
      const aiMsg: ChatMessage = { role: 'assistant', content: response, timestamp: Date.now() };
      setChatHistory(prev => [...prev, aiMsg]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const filteredSearchResults = useMemo(() => {
    if (!currentUser || !globalSearchTerm.trim()) return null;
    const term = globalSearchTerm.toLowerCase();
    return {
      problems: (currentUser.problems || []).filter(p => p.condition.toLowerCase().includes(term)),
      medications: (currentUser.medications || []).filter(m => m.name.toLowerCase().includes(term))
    };
  }, [currentUser, globalSearchTerm]);

  if (isLoading && !isAuth) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-indigo-300 font-bold uppercase tracking-widest text-xs">Initializing Vault...</p>
        </div>
      </div>
    );
  }

  if (!isAuth) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 lg:p-12 relative overflow-hidden">
        <div className="absolute inset-0 opacity-20">
          <div className="absolute top-[20%] left-[10%] w-96 h-96 bg-indigo-600 rounded-full blur-[150px] animate-pulse"></div>
          <div className="absolute bottom-[20%] right-[10%] w-96 h-96 bg-emerald-600 rounded-full blur-[150px] animate-pulse" style={{ animationDelay: '2s' }}></div>
        </div>

        <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-12 bg-white/5 backdrop-blur-2xl rounded-[3.5rem] overflow-hidden border border-white/10 shadow-2xl relative z-10">
          <div className="lg:col-span-5 bg-indigo-950 p-12 text-white flex flex-col justify-between relative border-r border-white/5">
            <div className="relative z-10">
              <div className="flex items-center gap-4 mb-16">
                <div className="w-14 h-14 bg-indigo-500 rounded-2xl flex items-center justify-center text-white text-2xl">{ICONS.LOCK}</div>
                <h1 className="text-2xl font-black uppercase tracking-tighter italic">{APP_NAME}</h1>
              </div>
              <h2 className="text-6xl font-black leading-tight tracking-tighter">Your <span className="text-indigo-400">Vault</span>,<br/>Your <span className="text-indigo-400">Rules</span>.</h2>
              <p className="text-lg text-indigo-200/70 mt-8 font-medium max-w-sm">Clinical history stored strictly on your local device. Decrypt with your unique ID.</p>
            </div>
          </div>

          <div className="lg:col-span-7 bg-slate-50 p-12 lg:p-20 flex flex-col justify-center relative">
            {isScanning && (
              <div className="absolute inset-0 z-50 bg-slate-50/80 backdrop-blur-md flex flex-col items-center justify-center">
                <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="font-black text-slate-800 uppercase tracking-widest text-xs">Authenticating Vault...</p>
              </div>
            )}

            {showRegSuccess ? (
              <div className="max-w-md mx-auto w-full text-center animate-pop-in">
                <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-[2rem] flex items-center justify-center text-5xl mx-auto mb-8 shadow-xl"><i className="fas fa-id-badge"></i></div>
                <h3 className="text-4xl font-black text-slate-800 tracking-tight mb-4">Vault Created</h3>
                <div className="bg-white p-10 rounded-[3rem] border-2 border-dashed border-indigo-200 mb-10">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Identity Health ID</p>
                  <p className="text-5xl font-mono font-black text-indigo-600 tracking-widest">{showRegSuccess}</p>
                </div>
                <button onClick={completeRegistration} className="w-full py-6 bg-slate-900 text-white font-black rounded-[2rem] shadow-2xl hover:bg-indigo-600 transition-all uppercase tracking-widest text-lg">Unlock My Vault</button>
              </div>
            ) : (
              <div className="max-w-md mx-auto w-full">
                <div className="relative bg-slate-200 p-1.5 rounded-[2.2rem] flex mb-16 shadow-inner">
                   <button onClick={() => setAuthMode('login')} className={`relative z-10 flex-1 py-4 text-[11px] font-black uppercase tracking-widest rounded-[1.8rem] transition-all ${authMode === 'login' ? 'bg-white text-indigo-600 shadow-xl' : 'text-slate-500'}`}>Existing User</button>
                   <button onClick={() => setAuthMode('register')} className={`relative z-10 flex-1 py-4 text-[11px] font-black uppercase tracking-widest rounded-[1.8rem] transition-all ${authMode === 'register' ? 'bg-white text-indigo-600 shadow-xl' : 'text-slate-500'}`}>New Patient</button>
                </div>

                {authMode === 'login' ? (
                  <form onSubmit={handleLogin} className="space-y-10 animate-slide-in">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Identity Access Key</label>
                      <input required value={loginId} onChange={(e) => setLoginId(e.target.value.toUpperCase())} placeholder="HID-XXXXXX" className="w-full px-8 py-6 rounded-[2.2rem] bg-white border border-slate-200 text-2xl font-mono uppercase focus:border-indigo-500 outline-none transition-all shadow-sm" />
                    </div>
                    <button type="submit" className="w-full bg-indigo-600 text-white font-black py-6 rounded-[2.2rem] text-lg hover:bg-indigo-700 shadow-xl transition-all">Secure Login <i className="fas fa-unlock ml-2"></i></button>
                  </form>
                ) : (
                  <form onSubmit={handleRegister} className="space-y-6 animate-slide-in max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
                    <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-4">
                      <input required name="name" placeholder="Full Legal Name" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-medium" />
                      <div className="grid grid-cols-2 gap-4">
                        <input required name="age" type="number" placeholder="Age" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                        <select required name="bloodGroup" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm font-bold uppercase">
                          <option value="">Blood Group</option>
                          {['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'].map(bg => <option key={bg} value={bg}>{bg}</option>)}
                        </select>
                      </div>
                      <input required name="phone" placeholder="Contact Phone" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                      <input required name="aadhaar" pattern="[0-9]{12}" placeholder="Aadhaar (12 Digits)" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                      <input required name="dob" type="date" className="w-full p-5 rounded-2xl bg-slate-50 border border-slate-100 outline-none text-sm" />
                    </div>
                    <button type="submit" className="w-full bg-emerald-600 text-white font-black py-6 rounded-[2.5rem] shadow-xl hover:bg-emerald-700 transition-all uppercase tracking-widest">Initialize Vault</button>
                  </form>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userName={currentUser?.profile?.name || 'Patient'} onLogout={handleLogout} isPremium={currentUser?.profile?.isPremium}>
      {activeTab === 'dashboard' ? (
        <div className="space-y-6 animate-pop-in">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className={`lg:col-span-2 rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden ${currentUser?.profile?.isPremium ? 'bg-slate-900' : 'bg-indigo-600'}`}>
              <div className="relative z-10">
                <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-8">Clinical Identity Passport</p>
                <h1 className="text-5xl font-mono font-black mb-12 tracking-wider">{currentUser?.profile?.healthId}</h1>
                <div className="grid grid-cols-3 gap-8">
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Blood Group</p><p className="font-black text-2xl">{currentUser?.profile?.bloodGroup}</p></div>
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Age</p><p className="font-black text-2xl">{currentUser?.profile?.age}</p></div>
                  <div><p className="text-[9px] uppercase font-bold opacity-60">Vault Status</p><p className="font-black text-sm uppercase tracking-widest text-emerald-400">Encrypted</p></div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-[2.5rem] p-10 shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center text-3xl mb-4">{ICONS.SHIELD_CHECK}</div>
              <p className="font-black text-emerald-600 italic">AES-256 Active</p>
              <p className="text-[10px] text-slate-400 mt-2">Data is isolated on your device.</p>
            </div>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {[
              { label: 'Conditions', val: (currentUser?.problems || []).length, icon: ICONS.MEDICAL },
              { label: 'Medications', val: (currentUser?.medications || []).length, icon: ICONS.MEDS },
              { label: 'Surgeries', val: (currentUser?.surgeries || []).length, icon: ICONS.SURGERY },
              { label: 'Allergies', val: (currentUser?.allergies || []).length, icon: ICONS.ALLERGY },
            ].map((s, i) => (
              <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-6 group hover:border-indigo-100 hover:shadow-lg transition-all">
                <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center text-2xl group-hover:bg-indigo-600 group-hover:text-white transition-all">{s.icon}</div>
                <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{s.label}</p><p className="text-2xl font-black text-slate-800">{s.val}</p></div>
              </div>
            ))}
          </div>
          {/* Government Aid Highlight Section */}
          <div className="bg-amber-50 rounded-[2.5rem] p-10 border border-amber-200 relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-10 text-amber-100 text-9xl -rotate-12 transition-transform group-hover:rotate-0">
              <i className="fas fa-landmark"></i>
            </div>
            <div className="relative z-10">
              <h3 className="text-xl font-black text-amber-900 mb-4 flex items-center gap-3">
                <i className="fas fa-landmark-dome"></i> Government Scheme Navigator
              </h3>
              <p className="text-sm text-amber-800/80 font-medium max-w-2xl leading-relaxed">
